// 跨卷人物的统一简介：同一人物在合集多卷出现时，各卷的原名、生卒、简介都以这里为准（势力仍按各卷）。
// 构建时（build.mjs）覆盖各书 PEOPLE_RAW 中的同名人物。简介写此人一生，不限于某一卷。
// 条目：[原名, 生卒, 简介, 适用的卷（可省）]；同名异人在第四项列出适用的卷。
const PEOPLE_COMMON = {
  // 西方卷一至十二：在后面几卷只写了 ['名', '势力', '', '', ''] 的跨卷人物，原名、生卒、简介取首次出场那卷
  穆尔西里一世: ['Mursili I', '?–约前1590', '哈图西里一世的孙辈与养子，继位后攻灭雅姆哈德，毁阿勒颇，约前 1595 年远袭巴比伦，结束汉谟拉比王朝，掠走马尔杜克神像。回国后不久被妹夫汉提里刺杀，赫梯随即陷入长期的内乱。'],
  拉美西斯三世: ['Ramesses III', '?–约前1155', '埃及第二十王朝的第二位法老，新王国最后一位强有力的君主。击退利比亚人，前 1177 年前后在陆上与海上击败海上民族，在哈布城修建陵庙记下战功。晚年发生工匠罢工，最后死于后宫的谋叛。'],
  希伦一世: ['Hieron I', '?–前467', '叙拉古的僭主，盖隆之弟，前 478 年继位。前 474 年在库迈海战大败埃特鲁里亚舰队，宫廷中聚集着品达、西蒙尼德斯、埃斯库罗斯等诗人。'],
  狄奥尼西奥斯一世: ['Dionysius I', '约前432–前367', '叙拉古的僭主，前 405 年借对迦太基的战争夺权，统治三十八年。多次与迦太基作战，前 397 年攻陷莫提亚；征服南意大利的希腊城市，把势力扩张到亚得里亚海。以修筑城防、发明弩炮著称，也写悲剧。'],
  奥林匹娅丝: ['Olympias', '约前375–前316', '伊庇鲁斯摩罗西亚王室的公主，腓力二世的王后，亚历山大的母亲，性格刚烈，笃信秘仪，与安提帕特长期不和。前 317 年回到马其顿，处死腓力三世，次年在皮德纳被卡山德围困，城破后被处死。'],
  西庇阿·纳西卡: ['Publius Cornelius Scipio Nasica', '约前227–前171后', '格奈乌斯·西庇阿之子，大西庇阿的堂兄弟。前 204 年被元老院评为全城“最优秀的人”，奉命到奥斯提亚迎接从佩西努斯运来的大母神像。前 191 年任执政官，大败波伊人，夺取其一半土地。'],
  罗慕路斯: ['Romulus', '传说前771–前716', '传说中罗马的建立者与第一位国王，战神马尔斯与阿尔巴隆加公主之子，与孪生兄弟雷穆斯由母狼哺育。他杀死雷穆斯，劫掠萨宾妇女，在一场暴风雨中消失，被奉为奎里努斯神。'],
  盖隆: ['Gelon', '约前540–前478', '格拉的僭主，前 485 年夺取叙拉古，迁徙人口建成大城，前 480 年与忒戎在希梅拉大败迦太基人，成为西西里最强的统治者，被叙拉古人尊为恩人。'],
  巨吉斯: ['Gyges', '?–约前644', '吕底亚国王，梅姆纳德王朝的开创者。希罗多德说他杀死国王坎道列斯，娶了王后。他遣使向亚述巴尼拔求援对付辛梅里安人，又派雇佣兵帮助普萨美提克一世，最后死于辛梅里安人之手。'],
  那波帕拉萨尔: ['Nabopolassar', '?–前605', '新巴比伦王朝的开创者，迦勒底人，前 626 年在巴比伦称王，与米底结盟，前 612 年攻陷尼尼微，前 605 年去世，传位给儿子尼布甲尼撒二世。'],
  基亚克萨雷斯: ['Cyaxares', '?–前585', '米底国王，迪奥塞斯之孙。摆脱斯基泰人的统治，改组军队，前 614 年攻陷亚述城，前 612 年与巴比伦联手攻陷尼尼微，后来又与吕底亚以哈吕斯河为界。'],
  约西亚: ['Josiah', '?–前609', '犹大王，八岁即位。在圣殿中发现律法书后推行宗教改革，把祭祀集中到耶路撒冷；前 609 年在美吉多阻击北上援助亚述的埃及法老尼科二世，战死。'],
  阿玛西斯: ['Amasis II', '?–前526', '埃及第二十六王朝的法老，前 570 至前 526 年在位。原为将军，被士兵拥立推翻阿普里斯；亲近希腊人，以瑙克拉提斯为希腊人的商港，征服塞浦路斯。死后半年埃及就被波斯征服。'],
  克洛伊索斯: ['Croesus', '?–?', '吕底亚的末代国王，约前 560 至前 546 年在位。征服小亚细亚的希腊城市，以富有闻名，铸造了最早的金银币。误解德尔斐神谕进攻波斯，萨第斯陷落后被俘，此后做了居鲁士与冈比西斯的顾问。'],
  梭伦: ['Solon', '约前638–约前558', '雅典的政治家与诗人，前 594 年任执政官，废除债务奴役，按财产划分公民等级，为雅典民主奠定了基础。改革后出游十年，希罗多德说他曾在萨第斯告诫克洛伊索斯。'],
  居鲁士二世: ['Cyrus II', '?–前530', '波斯帝国的建立者，安善王冈比西斯一世之子，前 559 年即位。前 550 年推翻米底，此后征服吕底亚、中亚与巴比伦，允许被掳的民族返乡，以宽容著称，被称为“居鲁士大帝”。征讨马萨格泰人时阵亡，葬于帕萨尔加德。'],
  冈比西斯二世: ['Cambyses II', '?–前522', '波斯国王，居鲁士二世之子，前 530 至前 522 年在位。前 525 年征服埃及，远征库什与阿蒙绿洲失败。在回国途中因伤去世。希罗多德把他描写为暴君与疯子。'],
  大流士一世: ['Darius I', '约前550–前486', '波斯国王，前 522 至前 486 年在位。杀死“僭位者”高墨达即位，一年内平定各地叛乱，刻下贝希斯敦铭文；划分行省，修筑御道，铸造金币，营建波斯波利斯，东征印度河，西征斯基泰与色雷斯。镇压爱奥尼亚起义后两次远征希腊。'],
  阿里斯塔哥拉斯: ['Aristagoras', '?–前497', '米利都的僭主，希斯提埃伊欧斯的女婿。纳克索斯之役失败后发动爱奥尼亚起义，到斯巴达与雅典求援，最后逃往色雷斯，在攻城时战死。'],
  克列奥美涅斯一世: ['Cleomenes I', '?–约前490', '斯巴达国王，在位近三十年，驱逐雅典僭主希庇阿斯，拒绝援助爱奥尼亚起义，在塞佩亚大败阿尔戈斯，晚年发疯而死。'],
  马铎尼斯: ['Mardonius', '?–前479', '波斯贵族，大流士的女婿。前 492 年远征色雷斯与马其顿，舰队在阿索斯山覆没；后来成为薛西斯远征希腊的主将，在普拉提亚战死。'],
  希庇阿斯: ['Hippias', '?–约前490', '庇西特拉图的长子，前 527 年继承僭主之位，弟弟希帕库斯被刺后统治变得严酷，前 510 年被斯巴达人驱逐，流亡波斯，前 490 年为波斯军引路到马拉松。'],
  地米斯托克利: ['Themistocles', '约前524–约前459', '雅典政治家，前 493 年任执政官，开始修建比雷埃夫斯港，力主建立海军，后来设计诱使波斯舰队在萨拉米斯海峡决战；雅典舰船是希腊联军的主力，名义上的统帅则是斯巴达人欧律比亚德斯。'],
  米太亚德: ['Miltiades', '约前550–前489', '雅典贵族，曾统治色雷斯的克森尼索半岛，参加爱奥尼亚起义后逃回雅典，前 490 年在马拉松指挥雅典军击败波斯。'],
  薛西斯一世: ['Xerxes I', '约前518–前465', '大流士一世与阿托莎之子，前 486 年继位，平定埃及与巴比伦的叛乱，前 480 年亲征希腊，萨拉米斯战败后撤回亚洲。在波斯波利斯完成了父亲的宫殿，前 465 年被近臣刺杀。'],
  阿里斯提德: ['Aristides', '约前530–约前468', '雅典政治家，以公正著称，号“公正者”，前 482 年被陶片放逐，大敌当前时回国，在萨拉米斯与普拉提亚作战，后来主持制定了提洛同盟的贡金。'],
  保萨尼阿斯: ['Pausanias', '?–约前470', '斯巴达摄政，列奥尼达的侄子，前 479 年统率希腊联军在普拉提亚击败波斯，后来因骄横与私通波斯失势，饿死在神庙里。'],
  伯利克利: ['Pericles', '约前495–前429', '克桑西普斯之子，母亲是克里斯提尼的侄女。厄菲阿尔特死后成为雅典民主派领袖，前 443 年起年年当选将军，主持修建帕特农神庙，奉行海上帝国政策，伯罗奔尼撒战争的第三年死于瘟疫。'],
  阿基达摩斯二世: ['Archidamus II', '?–约前427', '斯巴达国王，前 464 年大地震时临危组织公民自卫；前 432 年劝斯巴达人不要轻易开战，战争爆发后多次率军入侵阿提卡，这一阶段因此称“阿基达摩斯战争”。'],
  苏格拉底: ['Socrates', '约前470–前399', '雅典哲学家，以街头问答的方式探究德性，自己不著述，言行见于柏拉图与色诺芬的记载。曾参加波提狄亚与代利昂之战，前 406 年拒绝违法表决，前 399 年被判饮毒芹而死。'],
  蒂萨费尔涅斯: ['Tissaphernes', '?–前395', '波斯的萨第斯总督，在雅典与斯巴达之间两面周旋，用金钱让希腊人互相消耗。'],
  吕山德: ['Lysander', '?–前395', '斯巴达海军统帅，出身寒微，结交波斯王子居鲁士取得资金，前 405 年在羊河全歼雅典舰队，次年迫使雅典投降，在各地扶植亲斯巴达的十人寡头。'],
  小居鲁士: ['Cyrus the Younger', '约前424–前401', '波斯王大流士二世的少子，前 407 年起统辖小亚细亚，全力资助吕山德；后来起兵与兄长争夺王位，在库纳克萨战死。'],
  亚历山大三世: ['Alexander III', '前356–前323', '马其顿国王，腓力二世与奥林匹娅丝之子，亚里士多德的学生，史称亚历山大大帝。十八岁在喀罗尼亚统率骑兵，前 336 年即位后平定希腊，前 334 年东征，在格拉尼库斯河、伊苏斯、高加米拉三败波斯，占领埃及并建亚历山大里亚，追杀大流士三世至中亚，又越兴都库什山进入印度，在希达斯皮斯河击败波鲁斯，因士兵拒绝前进而折返。前 323 年在巴比伦病逝，年仅三十二岁，没有留下成年的继承人，帝国随即被部将瓜分。'],
  帕曼纽: ['Parmenion', '约前400–前330', '腓力二世最信任的将军，前 356 年击败伊利里亚人，前 336 年率先头部队进入小亚细亚，后随亚历山大东征，被亚历山大处死。'],
  狄摩西尼: ['Demosthenes', '前384–前322', '雅典最著名的演说家，自幼口吃，传说含着石子对着大海练习演说，一生以《反腓力辞》等演说号召雅典抵抗马其顿，促成雅典与忒拜联盟，喀罗尼亚战败后继续坚持，最后服毒自尽。'],
  福基翁: ['Phocion', '约前402–前318', '雅典将军与政治家，四十五次当选将军，生活俭朴，说话简短，主张与马其顿和平相处，晚年被雅典人以叛国罪处死，后来又被恢复名誉。'],
  安提帕特: ['Antipater', '约前399–前319', '腓力二世的老臣，亚历山大东征期间留守马其顿与希腊，前 331 年在麦加洛波利斯击败斯巴达王阿吉斯三世。亚历山大死后，他在拉米亚战争中镇压希腊人的起义，迫使雅典接受马其顿驻军；前 320 年的特里帕拉迪苏斯会议上成为帝国摄政，监护两位国王。次年病逝，临终把摄政之位交给波利伯孔而不是儿子卡山德，引发了新一轮内战。'],
  罗克珊娜: ['Roxana', '?–约前310', '粟特贵族奥克夏特斯的女儿，前 327 年嫁给亚历山大，亚历山大死后生下遗腹子亚历山大四世，母子后来被卡山德杀害。'],
  皮洛士: ['Pyrrhus of Epirus', '前319–前272', '伊庇鲁斯的摩罗西亚国王，亚历山大母亲奥林匹娅丝的堂侄。少年两度失国，伊普苏斯之战时随姐夫德米特里作战，后在托勒密的支持下复位，曾两度占有马其顿，前 280 至前 275 年在意大利与西西里同罗马和迦太基作战，“皮洛士式的胜利”一词即由此而来，在阿尔戈斯巷战中被屋瓦砸中身亡。'],
  基尼阿斯: ['Cineas', '?–约前277', '色萨利人，狄摩西尼的学生，以口才闻名，皮洛士的谋士与使者，皮洛士说基尼阿斯用言辞攻下的城市比他用武力攻下的还多。'],
  希伦二世: ['Hiero II', '约前308–前215', '叙拉古国王。原为将领，前 270 年前后击败马麦尔丁人后称王。第一次布匿战争初年与迦太基联手围攻墨西拿，失利后于前 263 年转与罗马结盟，此后近五十年始终是罗马的忠实盟友，为罗马军供应粮食。在位期间叙拉古繁荣安定，阿基米德为他设计了许多器械。九十高龄去世。'],
  阿庇乌斯·克劳狄乌斯·考德克斯: ['Appius Claudius Caudex', '?–?', '前 264 年任执政官，率罗马军第一次渡海进入西西里，解墨西拿之围，击退叙拉古与迦太基军。“考德克斯”意为木头，据说因他提倡造船而得名。'],
  汉尼拔: ['Hannibal Barca', '前247–前183', '迦太基名将，哈米尔卡·巴卡的长子。九岁随父赴西班牙，在祭坛前立誓永不与罗马为友。前 221 年继姐夫哈斯德鲁巴统率西班牙的迦太基军，前 219 年攻陷萨贡托，次年率军越比利牛斯山与阿尔卑斯山进入意大利，在特雷比亚河、特拉西梅诺湖与坎尼连败罗马军，此后在意大利转战十五年。前 203 年奉召回国，次年在扎马败于大西庇阿。战后任迦太基最高执政官（苏菲特）整顿财政，前 195 年被罗马逼迫出亡，投奔塞琉古王安条克三世，安条克战败后辗转克里特、比提尼亚，前 183 年罗马使者索要时服毒自尽。', ['buni', 'dongjin']],
  大西庇阿: ['Publius Cornelius Scipio Africanus', '前236–前183', '罗马统帅，同名执政官普布利乌斯·西庇阿之子。十七岁在提契诺河救父，坎尼之役后收拢残兵。前 210 年以未任高级官职之身受命统率西班牙军，次年奇袭新迦太基，前 206 年在伊利帕大败迦太基军，平定西班牙。前 205 年任执政官，次年渡海进攻阿非利加，焚毁迦太基与西法克斯的营地，前 202 年在扎马击败汉尼拔，得“阿非利加努斯”的称号。前 190 年随弟弟卢基乌斯东征安条克三世。晚年在加图等人发起的诉讼中受辱，退居利特尔农，前 183 年去世，与汉尼拔同年。', ['buni', 'dongjin']],
  马西尼萨: ['Masinissa', '约前238–前148', '东努米底亚马西利部的王子，早年在西班牙为迦太基作战，前 206 年转投大西庇阿。归国争位时被西努米底亚王西法克斯逐出，随罗马军进攻阿非利加，前 203 年擒获西法克斯，扎马之役中统率努米底亚骑兵立下大功，战后由罗马承认为统一的努米底亚国王。此后五十余年不断蚕食迦太基的土地，终于逼迫迦太基出兵抵抗，成为第三次布匿战争的导火索。九十岁去世，波利比乌斯称他是当时最出色的国王。', ['buni', 'dongjin']],
  腓力五世: ['Philip V of Macedon', '前238–前179', '马其顿安提柯王朝国王，前 221 年即位。同盟战争中联合亚该亚同盟攻打埃托利亚，坎尼之役后与汉尼拔结盟，引发第一次马其顿战争。前 202 年起与安条克三世瓜分托勒密的海外领地，在爱琴海与小亚细亚四处攻掠，招致第二次马其顿战争，前 197 年在库诺斯克法莱败于弗拉米尼努斯，退出希腊。晚年处死次子德米特里乌斯，抑郁而终。', ['buni', 'dongjin']],
  安条克三世: ['Antiochus III the Great', '约前242–前187', '塞琉古王国国王，前 223 年即位。第四次叙利亚战争在拉菲亚败于托勒密四世，此后平定小亚细亚的阿凯乌斯，前 212 至前 205 年东征亚美尼亚、帕提亚与巴克特里亚，直至印度，号称“大帝”。前 200 年在帕尼翁击败托勒密军，夺取科伊勒叙利亚。前 192 年应埃托利亚同盟之邀渡海进入希腊，在温泉关与马格尼西亚两败于罗马，前 188 年签订阿帕米亚和约，放弃陶鲁斯山以西的小亚细亚。前 187 年在埃利迈斯劫掠神庙时被杀。', ['buni', 'dongjin']],
  小西庇阿: ['Publius Cornelius Scipio Aemilianus Africanus', '前185–前129', '埃米利乌斯·保卢斯的次子，过继给大西庇阿之子，十七岁随生父参加彼得那之战。师从波利比乌斯，与莱利乌斯、帕奈提乌斯等组成爱好希腊文化的“西庇阿圈子”。第三次布匿战争中以未到法定年龄之身破格当选执政官，前 146 年攻陷并毁灭迦太基；前 134 年再任执政官，次年攻陷努曼提亚。他是提比略·格拉古的姐夫，却不赞成其改革，听说提比略被杀时引荷马诗句说“凡这样做的人都应如此灭亡”。前 129 年在为意大利盟邦争取权益期间，一天早晨被发现死在家中，死因成谜。', ['dongjin', 'sula']],
  提比略·格拉古: ['Tiberius Sempronius Gracchus', '前163–前133', '同名执政官与大西庇阿之女科尔内利娅的长子。前 137 年任财务官，在努曼提亚城下出面议和保全了二万罗马军，和约却被元老院否认。前 133 年任保民官，提出土地法，限制个人占有公地，把多余的公地分给贫民，罢免反对的同僚屋大维，又提议用阿塔罗斯三世的遗产资助分得土地的农民。竞选连任保民官的选举日，大祭司长西庇阿·纳西卡率元老与门客冲上卡皮托山，将他与三百名支持者打死，尸体扔进台伯河。这是罗马城内第一次公民流血的政治冲突。', ['dongjin', 'sula']],
  米西普萨: ['Micipsa', '?–前118', '马西尼萨的长子，前 148 年父亲死后由小西庇阿主持分国，掌管王都锡尔塔与国库，两个弟弟死后独掌努米底亚三十年，安定富庶，招徕希腊学者。收养侄子朱古达，派他率军援助小西庇阿攻打努曼提亚，临终把王国分给两个儿子与朱古达。', ['dongjin', 'sula']],
  加图: ['Marcus Porcius Cato', '前234–前149', '罗马政治家，图斯库鲁姆人，平民出身而以勤俭刚直著称。年轻时参加汉尼拔战争，任过大西庇阿的财务官，前 195 年任执政官平定西班牙，前 191 年在温泉关立功。前 184 年任监察官，严厉整饬风纪，打击希腊风尚与奢侈，又带头攻击西庇阿兄弟。晚年出使迦太基，见其复兴而深为忧惧，此后每次在元老院发言都以迦太基必须毁灭作结。著有《起源》与《农业志》，是第一部拉丁文罗马史与现存最早的拉丁文散文。', ['dongjin']],
  欧努斯: ['Eunus', '?–前132', '叙利亚出身的奴隶，在西西里恩纳的庄园劳作，以预言与口吐火焰的戏法赢得信众，约前 135 年领导奴隶起义，攻下恩纳，自称国王安条克，与阿克拉加斯一带的克利昂会合，众至数万。前 132 年执政官鲁皮利乌斯攻下恩纳，他逃入山洞被俘，死于狱中。', ['dongjin', 'sula']],
  // 卷十五、十六（苏拉、庞培与恺撒）
  恺撒: ['Gaius Julius Caesar', '前100–前44', '出身古老的尤利乌斯家族，马略的妻侄、秦纳的女婿。苏拉独裁时拒绝休妻，险些被杀。后来征服高卢，渡过卢比孔河发动内战，成为终身独裁官，前 44 年三月十五日遇刺。'],
  庞培: ['Gnaeus Pompeius Magnus', '前106–前48', '庞培·斯特拉波之子，十七岁随父围攻阿斯库鲁姆。前 83 年在皮凯努姆私募三个军团投奔苏拉，随后肃清西西里与阿非利加的平民派，得号“伟大的”，二十五岁以骑士身份举行凯旋。后来平定塞多留、海盗与米特拉达梯，重组东方，与恺撒、克拉苏结成三头同盟，最后在法萨卢斯败于恺撒，在埃及被杀。'],
  西塞罗: ['Marcus Tullius Cicero', '前106–前43', '阿尔皮努姆的骑士之子，罗马最著名的演说家、律师与文章家。前 80 年为罗斯基乌斯辩护成名，后来官至执政官，平定喀提林阴谋，被称为“祖国之父”，前 43 年死于后三头的公敌宣告。'],
  克拉苏: ['Marcus Licinius Crassus', '约前115–前53', '父兄死于前 87 年马略派的屠杀，逃亡西班牙，前 83 年投奔苏拉，在科林门之战中指挥获胜的右翼。在公敌财产的拍卖中低价购入大片地产，成为罗马首富。后来镇压斯巴达克起义，与庞培、恺撒结成三头同盟，在卡莱败于帕提亚，被杀。'],
  塞多留: ['Quintus Sertorius', '约前123–前72', '萨宾人，在阿劳西奥之战中负伤游过罗讷河生还，随马略打败辛布里人，曾化装成高卢人刺探敌情。同盟者战争中失去一只眼睛。前 87 年随秦纳攻入罗马，前 83 年出任西班牙总督，被苏拉的军队逐出后流亡毛里塔尼亚。前 80 年应卢西塔尼亚人之邀回到西班牙，屡败梅特卢斯与庞培，前 72 年被部下佩尔佩尔纳刺杀。'],
  梅特卢斯·皮乌斯: ['Quintus Caecilius Metellus Pius', '约前128–前63', '梅特卢斯·努米底库斯之子，因竭力为流亡的父亲求情，号“孝子”。同盟者战争中任大法官，前 83 年率军投奔苏拉，前 80 年与苏拉同任执政官，此后统军进讨西班牙的塞多留近十年，前 71 年与庞培一起凯旋。'],
  米特拉达梯六世: ['Mithridates VI Eupator', '前134–前63', '本都国王，前 120 年父亲被毒死后即位，据说少年时躲入山林，服毒以求百毒不侵，通晓二十二种语言。兼并克里米亚、科尔基斯与小亚美尼亚，与罗马争夺卡帕多西亚与比提尼亚。前 88 年席卷亚细亚，下令屠杀罗马人与意大利人；被苏拉逐回后又两次与罗马开战，前 63 年被儿子背叛，在克里米亚自尽。'],
  提格兰二世: ['Tigranes II the Great', '约前140–前55', '亚美尼亚国王，早年在帕提亚为人质，前 95 年割地赎身即位，兼并索菲尼，娶米特拉达梯六世的女儿。乘帕提亚内乱征服阿迪亚贝尼、戈尔迪埃内与阿特罗帕特尼，前 83 年入主叙利亚，自称“众王之王”，新建提格兰诺塞塔。前 69 年被卢库卢斯击败，前 66 年向庞培投降，保住亚美尼亚本土。此后作为罗马的“朋友与盟友”统治亚美尼亚，约前 55 年去世。'],
  // 卷十一之后的希腊化卷（xilahua）与前后几卷共有的人物
  托勒密二世: ['Ptolemy II Philadelphus', '前308–前246', '托勒密一世与贝勒尼刻之子，前 285 年与父亲共治，前 282 年独立为王，娶姐姐阿尔西诺伊二世，号“爱姐者”。在位期间亚历山大里亚的学术与宫廷最为繁盛，传说《圣经》的希腊文七十士译本始于他的提倡。'],
  安条克一世: ['Antiochus I Soter', '约前324–前261', '塞琉古一世与粟特贵族斯皮塔米尼斯之女阿帕玛之子，伊普苏斯之战中率骑兵作战，娶继母斯特拉托妮刻，前 292 年起统治东方诸省，父亲遇刺后继位，以“象战”击败加拉太人，号“救主”。'],
  安提柯二世: ['Antigonus II Gonatas', '约前320–前239', '德米特里一世之子，师从斯多葛派的芝诺，父亲被俘后守住希腊的几座要塞，前 277 年在吕西马其亚大败高卢人，取得马其顿王位，此后两度失而复得，奠定了安提柯王朝对马其顿的统治。'],
  芝诺: [['Zeno of Citium', '约前334–前262', '塞浦路斯基提翁人，据说因船难流落雅典，转而学习哲学，在雅典广场的彩绘柱廊讲学，创立斯多葛派，主张顺应自然与理性生活。', ['jiye', 'xilahua']], ['Zeno', '约425–491', '伊苏里亚山民的首领，原名塔拉西科迪萨，娶了利奥一世的女儿阿里阿德涅，改名芝诺。474 年儿子利奥二世夭折后成为皇帝，次年被巴西利斯库斯赶出君士坦丁堡，476 年复位。同年奥多亚克把西部的帝国徽章送给他，名义上奉他为全帝国的皇帝。488 年他把东哥特王狄奥多里克派往意大利讨伐奥多亚克。', ['xiluoma', 'chashidingni']]],
  阿拉图斯: ['Aratus of Sicyon', '前271–前213', '亚该亚同盟的领袖，前 251 年推翻西库翁的僭主，使之加入同盟，前 243 年夺取马其顿驻守的科林斯卫城，多次当选同盟将军。面对斯巴达克利奥米尼三世的进攻，转而请马其顿安提柯三世出兵。晚年与腓力五世不和，据说被腓力毒死。'],
  阿塔罗斯一世: ['Attalus I Soter', '前269–前197', '帕加马国王。击败加拉太人后称王，号“救主”。一度夺取塞琉古在陶鲁斯山以西的领地。第一次马其顿战争中与罗马同盟，协助罗马迎回大母神圣石，前 201 年联合罗得岛在开俄斯与腓力五世海战，引罗马东来，前 197 年在忒拜演说时中风，不久去世。'],
  阿萨息斯一世: ['Arsaces I', '?–约前211', '帕尼部落首领，前 238 年前后进入塞琉古的帕提亚行省，杀死总督，建立帕提亚王国（安息），此后历代国王都以阿萨息斯为号。'],
  克利奥米尼三世: ['Cleomenes III', '约前260–前219', '斯巴达国王，前 235 年即位。前 227 年发动政变，废除监察官，取消债务、重新分配土地，扩充公民，恢复吕库古的旧制，屡败亚该亚同盟。前 222 年在塞拉西亚败于马其顿王安提柯三世，逃往埃及，后在亚历山大里亚起事失败自杀。'],
  安提柯三世: ['Antigonus III Doson', '约前263–前221', '马其顿国王，前 229 年以王族身份为年幼的腓力五世摄政，后称王。应亚该亚同盟之请南下，以科林斯卫城为代价组织希腊同盟，在塞拉西亚击败斯巴达的克利奥米尼三世，随即回国击退伊利里亚人，次年去世。'],
  阿凯乌斯: ['Achaeus', '?–前213', '塞琉古王族，安条克三世的亲戚。前 223 年为新王收复被帕加马夺去的小亚细亚，前 220 年在萨第斯自立为王，前 213 年被安条克三世围困萨第斯，被人出卖擒获，处以肢解之刑。'],
  托勒密四世: ['Ptolemy IV Philopator', '约前244–前204', '托勒密王朝国王，号“爱父者”，前 222 年即位。在拉菲亚击败安条克三世，保住科伊勒叙利亚，但因征召埃及本地人入伍，此后埃及南部屡起叛乱。宠信大臣索西比乌斯，耽于享乐，死后宫廷内乱。'],
  斯科帕斯: ['Scopas of Aetolia', '?–前196', '埃托利亚将领，曾任埃托利亚同盟将军，后投托勒密王朝统率雇佣军，第五次叙利亚战争中在帕尼翁败于安条克三世，后在亚历山大里亚谋叛被处死。'],
  弗拉米尼努斯: ['Titus Quinctius Flamininus', '约前229–前174', '罗马统帅，三十岁出任执政官，主持第二次马其顿战争，前 197 年在库诺斯克法莱击败腓力五世，次年在地峡运动会上宣布希腊自由，被希腊人奉为救主。前 195 年讨伐斯巴达的纳比斯，次年撤军回国。前 183 年出使比提尼亚，索要汉尼拔，致其自尽。'],
  纳比斯: ['Nabis', '?–前192', '斯巴达国王，前 207 年夺位，释放希洛人、没收富人财产、分配土地，被敌对的史家称为僭主。前 195 年被弗拉米尼努斯击败，交出阿尔戈斯与沿海城镇，前 192 年被前来援助他的埃托利亚人刺杀。'],
  菲洛皮门: ['Philopoemen', '约前253–前183', '亚该亚同盟的将军，八次当选。改革同盟军队，前 207 年在曼丁尼亚击败斯巴达，前 192 年把斯巴达并入同盟。主张在罗马面前维护同盟的尊严。前 183 年讨伐叛离的美塞尼亚时被俘，被迫饮毒而死，被称为“最后一位希腊人”。'],
  卢基乌斯·西庇阿: ['Lucius Cornelius Scipio Asiaticus', '?–前183后', '大西庇阿的弟弟，前 190 年任执政官，在哥哥辅佐下进军亚细亚，在马格尼西亚击败安条克三世，得号“亚细亚提库斯”。后被控侵吞安条克的赔款，被判罚款。'],
  欧迈尼斯二世: ['Eumenes II Soter', '?–前159', '帕加马国王，前 197 年继阿塔罗斯一世即位。与罗马结盟，在马格尼西亚战役中立功，阿帕米亚和约后领地扩大数倍，修建帕加马大祭坛与图书馆。屡向罗马控诉珀尔修斯，在德尔斐险遭刺杀；彼得那之后又被罗马猜忌冷落。'],
  珀尔修斯: ['Perseus of Macedon', '约前212–前166', '马其顿安提柯王朝末代国王，腓力五世长子，诬告弟弟德米特里乌斯致其被杀，前 179 年即位。第三次马其顿战争中在彼得那大败，逃到萨莫色雷斯后投降，在保卢斯的凯旋式上游街示众，囚死于阿尔巴·福肯斯。'],
  安条克四世: ['Antiochus IV Epiphanes', '约前215–前164', '塞琉古王国国王，安条克三世之子，曾在罗马为人质。前 175 年即位，两次远征埃及，被罗马使者在埃琉西斯画圈逼退。推行希腊化，在耶路撒冷圣殿设宙斯祭坛，激起马加比起义。前 164 年东征帕提亚途中病死。'],
  埃米利乌斯·保卢斯: [['Lucius Aemilius Paullus', '?–前216', '前 219 年任执政官，击败法罗斯的德米特里乌斯。前 216 年再任执政官，主张谨慎，与同僚瓦罗意见不合，坎尼之战中受伤，拒绝骑兵军官让马给他逃走，战死阵中。其子即后来在彼得那击败马其顿的同名统帅。', ['buni']], ['Lucius Aemilius Paullus Macedonicus', '约前229–前160', '坎尼阵亡的同名执政官之子，前 182 年、前 168 年两任执政官，在彼得那击败珀尔修斯，结束马其顿王国，得号“马其顿尼库斯”。奉命洗劫伊庇鲁斯。为人廉洁，只从马其顿王宫取走藏书给儿子们。凯旋前后两个幼子相继夭折。长子过继给费边家，次子过继给大西庇阿之子，即小西庇阿。', ['dongjin', 'xilahua']]],
  波皮利乌斯·莱纳斯: ['Gaius Popillius Laenas', '?–?', '前 172 年、前 158 年两任执政官。前 168 年出使埃及，在亚历山大里亚城外的埃琉西斯以杖画圈，逼安条克四世撤出埃及。'],
  波利比乌斯: ['Polybius', '约前200–约前118', '希腊史家，亚该亚同盟骑兵长官，菲洛皮门的追随者。彼得那之后作为一千名人质之一被押到罗马，成为小西庇阿的老师与挚友，随他目睹迦太基毁灭。科林斯毁灭后协助罗马安排希腊事务。著《历史》四十卷，记前 264 至前 146 年罗马如何在不到五十三年间征服世界，本合集卷十三《布匿战争》、卷十四《罗马东进》多据其书。'],
  犹大·马加比: ['Judas Maccabeus', '?–前160', '莫迪因祭司马他提亚之子，领导犹太人反抗塞琉古王安条克四世，前 164 年收复耶路撒冷，洁净圣殿，与罗马结盟，前 160 年在埃拉沙战死。'],
  穆米乌斯: ['Lucius Mummius Achaicus', '?–?', '新贵出身，前 146 年任执政官，击败亚该亚同盟，焚毁科林斯，把大批希腊艺术品运往罗马，得号“亚该亚库斯”。据说他不懂艺术，警告运送名画的船长，若有损坏须赔新的。'],
  米特拉达梯一世: ['Mithridates I of Parthia', '?–前132', '帕提亚国王，约前 171 年即位，征服米底、巴比伦尼亚、埃利迈斯与波西斯，俘获塞琉古王德米特里乌斯二世，把帕提亚由伊朗东北的小国变成横跨伊朗高原与两河流域的大国，自称“众王之王”。'],
  西门: ['Simon Thassi', '?–前135', '马他提亚之子，犹大·马加比的兄弟。前 142 年迫使塞琉古免除犹太的贡赋，前 140 年被推为世袭的大祭司与统帅，建立哈斯蒙尼王朝，前 135 年被女婿谋杀。'],
  // 恺撒卷与奥古斯都卷共有的人物
  安东尼: ['Marcus Antonius', '前83–前30', '演说家安东尼的孙子，曾在叙利亚随加比尼乌斯作战，后成为恺撒的部将。前 49 年任保民官，被逐出元老院后投奔恺撒，在法萨卢斯指挥左翼，此后代恺撒管理意大利。前 44 年任执政官，在牧神节上向恺撒献王冠。恺撒死后与屋大维、雷必达结成后三头，最后与克娄巴特拉一起在亚克兴战败，自杀。'],
  马库斯·布鲁图斯: ['Marcus Junius Brutus', '前85–前42', '小加图的外甥，自称是驱逐王政的卢基乌斯·布鲁图斯的后人，以好学与正直著称。内战中追随杀父仇人庞培，法萨卢斯之后被恺撒宽恕重用，任大法官。前 44 年与卡西乌斯领导刺杀恺撒，后到东方募兵，前 42 年在腓立比败于安东尼与屋大维，自杀。'],
  卡西乌斯: ['Gaius Cassius Longinus', '?–前42', '前 53 年在卡莱战役中任克拉苏的财务官，率残部守住叙利亚，击退帕提亚人。内战中站在庞培一方，后被恺撒宽恕，任大法官。前 44 年刺杀恺撒的主谋，前 42 年在腓立比误以为布鲁图斯已败，令奴隶杀死自己。'],
  德奇穆斯·布鲁图斯: ['Decimus Junius Brutus Albinus', '约前81–前43', '恺撒在高卢的部将，前 56 年指挥舰队歼灭维尼蒂人，前 49 年从海上围攻马西利亚。深受恺撒信任，在遗嘱中被列为第二顺位继承人，却参与了刺杀，三月望日那天亲自到恺撒家中劝他去元老院。前 43 年在高卢被部下抛弃，被杀。'],
  克娄巴特拉七世: ['Cleopatra VII Philopator', '前69–前30', '托勒密王朝最后的女王，据说是这个马其顿王室中唯一学会埃及语的统治者，通晓多种语言。前 48 年借恺撒之力复位，与他生下恺撒里昂，后来与安东尼结盟并结婚。前 31 年在亚克兴战败，次年在亚历山大里亚自杀，埃及并入罗马。'],
  许尔堪二世: ['Hyrcanus II', '?–前30', '哈斯蒙尼王朝的大祭司，亚历山大·扬尼斯与撒罗米·亚历山德拉之子。与弟弟阿里斯托布鲁斯二世争位，前 63 年在庞培支持下被立为大祭司与民族首领，实权渐归以土买人安提帕特一家。后来被帕提亚人俘虏，最终被希律处死。'],
  雷必达: [['Marcus Aemilius Lepidus', '?–前77', '前 78 年任执政官，曾在苏拉的公敌宣告中致富，苏拉一死就要废除他的法律。被派往埃特鲁里亚平乱后反而率军进逼罗马，前 77 年被卡图卢斯与庞培击败，逃往撒丁岛病死。他的儿子就是后来的后三头之一雷必达。', ['kaisa']], ['Marcus Aemilius Lepidus', '约前89–前13/12', '前 78 年那位执政官雷必达之子，前 49 年恺撒渡过卢比孔河后任大法官，替恺撒留守罗马，前 46 年任执政官，又任恺撒的骑兵长官。恺撒遇刺后率兵进城，被选为大祭司，前 43 年在外高卢接纳了战败的安东尼，与安东尼、屋大维结成后三头，分得阿非利加。前 36 年在西西里企图与屋大维争夺塞克斯图斯·庞培的军队，被士兵抛弃，剥夺权力，只保留大祭司之职，在奇尔切伊软禁到死。', ['aogusidu']]],
  // 奥古斯都卷与朱里亚—克劳狄卷共有的人物
  提比略: ['Tiberius Claudius Nero', '前42–公元37', '莉薇娅与前夫之子，奥古斯都的继子，罗马第二位皇帝。少年从军，前 20 年从帕提亚手中取回军旗，又征服雷蒂亚、潘诺尼亚，平定伊利里库姆大起义，在日耳曼收拾瓦卢斯战败后的残局，是当时最出色的将领。被迫与爱妻维普萨尼娅离婚、娶尤利娅后，自请退隐罗得岛七年，公元 4 年才被奥古斯都收养，公元 14 年继位。在位二十三年，节俭务实，不事扩张，国库充盈，却阴郁多疑，晚年退居卡普里岛，先后把朝政交给塞扬努斯与马克罗，叛国罪的审判与告密使罗马人人自危。公元 37 年死于米塞努姆。'],
  日耳曼尼库斯: ['Germanicus Julius Caesar', '前15–公元19', '老德鲁苏斯之子，奥古斯都的外甥孙，公元 4 年被伯父提比略收养。随提比略平定伊利里库姆大起义，公元 14 年起统率莱茵河的八个军团，平息哗变，此后三年进攻日耳曼，找回瓦卢斯丢失的鹰旗。公元 17 年被派往东方，与叙利亚总督皮索交恶，公元 19 年死于安条克，人们相信他是被毒死的。他深受军队与民众爱戴，妻子是阿格里帕的女儿阿格里皮娜，儿子是皇帝卡利古拉，女儿小阿格里皮娜是尼禄的母亲。'],
  莉薇娅: ['Livia Drusilla', '前58–公元29', '克劳狄家族的贵族女子，十六岁嫁给提比略·克劳狄·尼禄，生下提比略。前 38 年怀着次子德鲁苏斯时被屋大维看中，与前夫离婚，嫁给屋大维，两人结婚五十一年，没有共同的孩子。她精明谨慎，是奥古斯都最亲近的顾问，被后世怀疑为让儿子继位而害死了奥古斯都的其他继承人。奥古斯都在遗嘱中把她收为养女，赐名尤利娅·奥古斯塔。'],
  李维: ['Titus Livius', '前59–公元17', '帕塔维乌姆（今帕多瓦）人，没有担任过官职，也没有从过军，毕生在罗马写作罗马史。《建城以来史》一百四十二卷，从罗马建城写到前 9 年，今存第一至十卷与第二十一至四十五卷，罗马早期的传说与汉尼拔战争主要靠他流传下来。'],
  奥维德: ['Publius Ovidius Naso', '前43–公元17', '苏尔莫的骑士之子，放弃仕途专心写诗，以《恋歌》《爱的艺术》《女杰书简》风靡罗马。他的《变形记》十五卷把两百多个希腊罗马神话串成一部从开天辟地到恺撒成神的长诗，是后世欧洲文学与绘画取材最多的古典作品。公元 8 年被奥古斯都流放到黑海边的托弥，原因至今是谜，在那里写了《哀怨集》与《黑海书简》，死于流放地。'],
  阿尔凯劳斯: ['Archelaus of Cappadocia', '?–公元17', '本都将领阿尔凯劳斯的曾孙。前 36 年被安东尼立为卡帕多西亚国王，亚克兴之后被屋大维保留，统治五十年，还得到小亚美尼亚与西里西亚的一部分。晚年得罪了提比略，公元 17 年被召到罗马受审，不久死去，王国改为行省。'],
  马罗博杜乌斯: ['Maroboduus', '约前30–公元37', '马科曼尼人的贵族，少年时在罗马生活过，熟悉罗马的军事与统治。约前 9 年德鲁苏斯进攻时，他带领族人迁到波希米亚，统一周边诸部，建立了拥有七万步兵与四千骑兵的王国。公元 6 年险些遭到提比略十二个军团的夹攻，因大起义得以与罗马议和。条顿堡之后拒绝与阿米尼乌斯联手，后来被推翻，在拉文纳流亡十八年而死。'],
  阿米尼乌斯: ['Arminius', '约前18–公元21', '切鲁西人首领的儿子，青年时在罗马军中统领日耳曼辅助部队，获得罗马公民权与骑士身份。公元 9 年在条顿堡森林伏击瓦卢斯，全歼三个军团，使罗马放弃了征服莱茵河以东的计划。此后与日耳曼尼库斯连年交战，又击败马罗博杜乌斯，最后被想称王的同族亲人杀死。十九世纪的德国人奉他为民族英雄，称他“赫尔曼”。'],
  耶稣: ['Jesus of Nazareth', '约前6/前4–约公元30/33', '加利利拿撒勒的犹太人，据福音书生于希律王晚年的伯利恒，在拿撒勒长大。约公元 28 年起在加利利一带传道、治病，宣讲上帝之国，收了十二门徒，在耶路撒冷的逾越节期间被犹太长官本丢·彼拉多钉死在十字架上。他的门徒宣称他已复活，由此产生了基督教。'],
  希律·安提帕: ['Herod Antipas', '前20以前–公元39以后', '大希律与马尔塔塞之子，亚基老的弟弟，统治加利利与佩利亚四十多年。他在加利利湖边建立了以提比略命名的提比里亚城，娶了异母兄弟的妻子希罗底，因此斩了施洗约翰。《路加福音》说彼拉多曾把耶稣送到他那里受审。'],
  // 卷十八、十九共有
  尤利乌斯·奇维利斯: ['Gaius Julius Civilis', '?–?', '巴达维人的王族，统领巴达维辅助部队二十五年，失去一只眼睛，自比汉尼拔与塞多留。尼禄时被诬叛国押往罗马，加尔巴释放了他。公元 69 年起兵，联合日耳曼诸部与高卢的特雷维里人、林贡人，一度攻破莱茵河上的大部分罗马营地，公元 70 年被韦斯巴芗的将领凯里亚利斯击败，议和而终。'],
  韦斯巴芗: ['Titus Flavius Vespasianus', '9–79', '萨宾的骑士家庭出身，以军功跻身元老。公元 43 年起在不列颠统领第二军团，征服西南部。尼禄时曾因在皇帝的演唱会上打瞌睡而失宠，公元 67 年被派去镇压犹太起义。公元 69 年七月被东方军团拥立为帝，十二月进入罗马，开创弗拉维王朝，在位十年，平定犹太与巴达维人的起义，整顿财政，连尿也要征税，开工修建罗马大斗兽场。公元 79 年病死于萨宾故乡，临终说“皇帝应该站着死”。'],
  提图斯: ['Titus Flavius Vespasianus', '39–81', '韦斯巴芗的长子，在克劳狄乌斯的宫中与不列塔尼库斯一同长大。随父亲平定犹太，公元 69 年起统领犹太战争，次年攻陷耶路撒冷，焚毁圣殿。公元 79 年继父位为帝，与犹太公主贝雷妮丝的恋情因民众反对而告终。在位两年，遇上维苏威火山爆发与罗马大火，为大斗兽场举行了百日落成庆典，以仁厚闻名，常说“朋友们，我虚度了一天”，公元 81 年病死。'],
  图密善: ['Titus Flavius Domitianus', '51–96', '韦斯巴芗的幼子，公元 69 年十二月维特利乌斯的士兵攻上卡皮托山时，化装成伊西斯的祭司逃脱。公元 81 年继兄长提图斯为帝，征卡蒂人，在日耳曼修筑边墙，与达契亚的德西巴卢斯作战后议和。他勤于政务，修复了罗马城，晚年专横多疑，自称“主人与神”，迫害元老与哲学家，公元 96 年被宫中的人刺杀，元老院下令抹去他的名字，弗拉维王朝随之结束。'],
  穆基阿努斯: ['Gaius Licinius Mucianus', '?–约77', '叙利亚总督，能言善辩，与韦斯巴芗本来不和，在提图斯的调解下和好，并力劝韦斯巴芗称帝。公元 69 年带兵西进，途中击退渡过多瑙河的达契亚人，到罗马时内战已经结束，在韦斯巴芗回来之前代他主持朝政。此后三次任执政官，是弗拉维王朝初年最有权势的人，还写过一部记载东方奇闻的书，常被老普林尼引用。'],
  希律·亚基帕二世: ['Herod Agrippa II', '27–约93', '亚基帕一世之子，父亲死时年仅十七岁，在罗马宫廷中长大，后来陆续得到黎巴嫩的卡尔基斯与加利利湖以东的封地，并有权任命大祭司。《使徒行传》说保罗曾在他面前申辩。犹太战争中站在罗马一边，劝耶路撒冷人不要造反，战后移居罗马，是希律家族最后一位国王。'],
  约瑟夫斯: ['Flavius Josephus', '37–约100', '耶路撒冷的祭司贵族，原名约瑟·本·马提亚。犹太战争中任加利利的起义军统帅，约塔帕塔陷落后投降，预言韦斯巴芗将做皇帝，获释后随提图斯围攻耶路撒冷，改从弗拉维家族的姓。晚年在罗马写成《犹太战记》《犹太古史》与自传，是了解这一时期犹太与早期基督教的最重要史料。'],
  沃洛加西斯一世: ['Vologases I', '?–约78', '帕提亚国王，约公元 51 年即位，把弟弟梯里达底立为亚美尼亚国王，与罗马的科尔布洛周旋十余年，最后达成由罗马为梯里达底加冕的妥协。据说他下令搜集祆教的经典《阿维斯塔》，在钱币上首次使用帕提亚文字。'],
  // 卷十九、二十共有
  康茂德: ['Lucius Aurelius Commodus', '161–192', '马可·奥勒留与小福斯蒂娜之子，与孪生兄弟同生于安敦尼死后数月，是第一位“生于紫室”的皇帝。五岁被立为恺撒，十五岁随父亲在多瑙河作战，公元 177 年成为共治的奥古斯都。父亲死后与马科曼尼人议和回到罗马，后来沉迷于在斗兽场里扮演赫拉克勒斯与角斗士，把罗马改名为“康茂德城”，公元 192 年最后一天被情妇马尔基娅与近卫军长官合谋毒杀未死，由角斗士纳尔基苏斯扼死。'],
  庞培亚努斯: ['Tiberius Claudius Pompeianus', '约125–193后', '叙利亚安条克人，骑士出身，凭军功跻身元老。卢基乌斯·维鲁斯死后，马可把寡居的女儿卢基拉嫁给他。他是马科曼尼战争中马可最信任的将领，曾把入侵意大利的马科曼尼人与夸狄人赶回多瑙河北。马可死后劝康茂德继续作战，没有被采纳，后来退隐，佩蒂纳克斯即位时曾回到元老院。'],
  // 卷二十、二十一共有
  戴克里先: ['Gaius Aurelius Valerius Diocletianus', '约244–约311', '达尔马提亚萨罗纳附近卑微家庭出身，原名狄奥克莱斯，从军升任努梅里安的卫队长。公元 284 年在尼科米底亚被拥立，次年击败卡里努斯。他建立四帝共治，把行省划小，分开军政，改革税制与币制，宫廷仪式模仿东方君主，开始了史称“君主制”的晚期帝国。303 年发动最后一次大规模的基督徒迫害，305 年主动退位，在斯普利特的宫殿里种菜终老。'],
  // 卷二十一、二十二共有
  约维安: ['Flavius Jovianus', '331–364', '潘诺尼亚辛吉杜努姆人，禁卫军军官的儿子，随尤利安东征时任禁卫军首领。363 年尤利安死后被军队推举为帝，与沙普尔二世订立和约，割让尼西比斯等地，带领军队撤回罗马境内。他是基督徒，恢复了教会的特权。在位八个月，364 年二月死于前往君士坦丁堡的途中，据说是被炭火的烟熏死的。'],
  阿米阿努斯·马塞利努斯: ['Ammianus Marcellinus', '约330–约395', '安条克的希腊人，出身良好，在骑兵统帅乌尔西奇努斯麾下当护卫军官，到过高卢与美索不达米亚，359 年亲历阿米达之围，363 年随尤利安东征。晚年在罗马用拉丁文写了三十一卷《历史》，接续塔西佗，从涅尔瓦写到 378 年阿德里安堡之战，现存后十八卷。他自称“一个曾经当过兵的希腊人”，叙事公允，被认为是塔西佗之后最伟大的罗马史家。'],
  沙普尔二世: ['Shapur II', '309–379', '萨珊波斯的万王之王，霍尔米兹德二世的遗腹子，据说在出生前就被加冕，在位七十年。成年后讨伐阿拉伯人，据说刺穿俘虏的肩膀，被阿拉伯人称为“肩膀的主人”。他三次围攻尼西比斯不下，359 年攻陷阿米达，363 年打退尤利安的进攻，迫使约维安割地求和，后来又吞并了亚美尼亚。他迫害境内的基督徒，视之为罗马的内应。'],
  乌尔菲拉: ['Ulfilas (Wulfila)', '约311–383', '哥特人中卡帕多西亚俘虏的后裔，约 341 年被尼科米底亚的优西比乌祝圣为哥特人的主教，在多瑙河北岸传教七年，348 年因哥特人迫害基督徒，带着信徒迁入罗马的默西亚。他创制哥特字母，把圣经译成哥特语，这是现存最早的日耳曼语文献。他信奉阿里乌派，使日耳曼诸族大多接受了阿里乌派的基督教。'],
  // 卷二十二、二十三共有
  奥多亚克: ['Odoacer', '约433–493', '多瑙河中游斯基里人或鲁基人的首领，父亲埃德科曾是阿提拉的亲信。他在意大利的罗马军中任职，476 年被雇佣军推举为王，废黜罗慕路斯·奥古斯都路斯，把帝国的徽章送回君士坦丁堡，名义上以东罗马皇帝的代理人身份统治意大利，保留了元老院与罗马的官制。他后来征服了达尔马提亚与西西里。493 年被东哥特王狄奥多里克攻破拉文纳，在宴会上被亲手杀死。'],
  盖萨里克: ['Gaiseric (Genseric)', '约389–477', '哈斯丁汪达尔王戈迪吉塞尔的私生子，428 年继任汪达尔与阿兰人的国王。次年率全族渡海进入阿非利加，439 年攻占迦太基，建立汪达尔王国。他组建舰队，占领撒丁、科西嘉、巴利阿里与西西里的一部分，455 年洗劫罗马，468 年在邦角击溃东西罗马的联合舰队。他信奉阿里乌派，迫害正统派的教士。统治近五十年，是五世纪最成功的蛮族国王。'],
  // 卷二十三、二十四共有
  霍斯劳一世: ['Khosrow I Anushirvan', '?–579', '卡瓦德一世之子，531 年即位，号“阿努希尔万”（不朽的灵魂）。他镇压马兹达克派，改革土地税与军制，建立了萨珊王朝的鼎盛时代。他与查士丁尼订立永久和约，又在 540 年撕毁和约洗劫安条克，为拉齐卡与罗马打了二十年仗，562 年订立五十年和约；在东方与突厥联手灭了嚈哒。他赞助学术，收留雅典的哲学家，组织翻译希腊、印度的著作，被后世波斯与阿拉伯人奉为明君的典范。'],
  // 卷二十四、二十五共有
  穆阿维叶: ['Mu\'awiya ibn Abi Sufyan', '约602–680', '艾布·苏富扬之子，630 年随父皈依，曾任穆罕默德的书记。639 年起任叙利亚总督二十年，建立了阿拉伯人的第一支海军，攻掠塞浦路斯与罗得岛。奥斯曼被杀后他拒绝承认阿里，在隋芬与阿里对峙，661 年成为唯一的哈里发，定都大马士革，开创倭马亚王朝，在位到 680 年，生前立儿子叶齐德为继承人。'],
  君士坦斯二世: ['Constans II', '630–668', '希拉克略之孙，君士坦丁三世之子，641 年十一岁即位。在位期间埃及、亚美尼亚相继失去，655 年在船桅之战中惨败；他颁布《定型》禁止讨论基督意志问题，逮捕教宗马丁一世。663 年迁居意大利与西西里，668 年在叙拉古的浴室中被侍从刺杀。'],
  侯赛因: ['Husayn ibn Ali', '626–680', '阿里与法蒂玛的次子，穆罕默德的外孙。他拒绝承认穆阿维叶之子叶齐德的继承，680 年在卡尔巴拉被倭马亚军队围攻，与家人随从一同遇难，什叶派每年在阿舒拉节纪念他。什叶派尊他为第三位伊玛目。'],
  // 卷二十五、二十六共有
  丕平: ['Pepin the Short', '714–768', '查理·马特之子，绰号“矮子”。741 年与兄长卡洛曼分治法兰克，747 年起独掌大权。751 年经教宗认可废黜墨洛温王朝的末代国王，自立为王，开创加洛林王朝；754 年教宗为他涂油。他两次出兵意大利打败伦巴第人，把拉文纳等地献给教宗，这就是“丕平献土”。他是查理曼的父亲。'],
  君士坦丁五世: ['Constantine V', '718–775', '利奥三世之子，741 年即位，在位三十四年。他多次打败阿拉伯人与保加尔人，754 年召开希耶里亚会议谴责圣像崇拜，迫害修道院，被崇拜圣像的修士们恶意称为“粪名者”，却深受军队爱戴。'],
  圣卜尼法斯: ['Saint Boniface (Wynfrith)', '约675–754', '威塞克斯的修士，原名温弗里斯，719 年受教宗格列高利二世派遣到日耳曼传教，在黑森砍倒雷神橡树，建立美因茨等主教区，改革法兰克教会，被称为“日耳曼人的使徒”。754 年在弗里斯兰传教时被杀，葬在富尔达修道院。'],
  萨法赫: ['Abu al-Abbas al-Saffah', '约721–754', '先知的叔父阿拔斯的玄孙，749 年在库法被拥立为第一任阿拔斯哈里发，750 年推翻倭马亚王朝，大肆清洗倭马亚家族。在位四年病逝，弟弟曼苏尔继位，修建了巴格达。'],
  艾斯图尔夫: ['Aistulf', '?–756', '伦巴第国王，749 年即位，751 年攻下拉文纳，灭亡东罗马的拉文纳总督区，进而威胁罗马。754 与 756 年两次被法兰克的丕平打败，被迫把拉文纳等地交给教宗，756 年打猎时坠马而死。'],
  // 卷二十六、二十七共有
  秃头查理: ['Charles the Bald', '823–877', '虔诚者路易与第二任妻子朱迪丝之子。父亲为他分封领地引发了兄长们的反叛。843 年凡尔登条约后得到西法兰克王国，875 年在罗马加冕为皇帝。'],
  洛泰尔一世: ['Lothair I', '795–855', '虔诚者路易的长子，817 年被立为共治皇帝和帝国的继承人。父亲死后要求两个弟弟服从自己，841 年在丰特努瓦战败，843 年凡尔登条约后保有皇帝称号与中法兰克王国。'],
  日耳曼人路易: ['Louis the German', '约806–876', '虔诚者路易之子，817 年分得巴伐利亚。与弟弟秃头查理联手对抗洛泰尔，842 年两人在斯特拉斯堡会盟，843 年得到莱茵河以东的东法兰克王国，被视为德意志王国的奠基者。'],
  阿卜杜勒·拉赫曼二世: ['Abd al-Rahman II', '792–852', '后倭马亚王朝的第四位埃米尔，822 年继位。他仿照巴格达改革宫廷与官制，扩建科尔多瓦大清真寺，礼遇音乐家齐尔亚布，科尔多瓦的文化在他的时代开始繁荣。'],
  // 卷二十七、二十八共有
  奥托一世: ['Otto I the Great', '912–973', '捕鸟者亨利之子，936 年在亚琛加冕。他平定了诸公爵的叛乱，951 年成为意大利国王，955 年在莱希菲尔德大败马扎尔人，962 年在罗马加冕为皇帝，通常被视为神圣罗马帝国的第一位皇帝，人称“奥托大帝”。'],
  阿德尔海德: ['Adelaide of Italy', '约931–999', '勃艮第国王鲁道夫二世之女，嫁给意大利国王洛泰尔二世，丈夫死后被贝伦加尔二世囚禁，逃出后嫁给奥托一世。962 年与奥托一同加冕，后来为孙子奥托三世摄政，被尊为圣徒。'],
  教宗约翰十二世: ['Pope John XII', '约937–964', '罗马贵族阿尔贝里克之子，十八岁成为教宗，生活放荡。962 年为奥托一世加冕，随即反悔，963 年被奥托召开的宗教会议废黜。'],
  尼基弗鲁斯·福卡斯: ['Nikephoros II Phokas', '约912–969', '卡帕多西亚军事贵族福卡斯家族的将领，961 年收复克里特，962 年攻下阿勒颇，963 年即位为皇帝，人称“撒拉森人的白死神”。'],
  彼得一世: ['Peter I of Bulgaria', '?–970', '西美昂一世之子，927 年即位，与东罗马议和，娶罗曼努斯一世的孙女，东罗马承认他的沙皇称号。'],
  奥尔加: ['Olga of Kiev', '约890–969', '伊戈尔的妻子，丈夫被杀后为儿子斯维亚托斯拉夫摄政，向德列夫利安人复仇，整顿贡赋制度。约 957 年访问君士坦丁堡并受洗，是第一位皈依基督教的罗斯统治者，被东正教会尊为圣徒。'],
  赛弗·道莱: ['Sayf al-Dawla', '916–967', '哈姆丹家族的阿里，944 年取得阿勒颇，此后二十多年与东罗马交战。他的宫廷聚集了诗人穆太奈比与哲学家法拉比。'],
  // 卷二十八、二十九共有
  希尔德布兰德: ['Hildebrand (Pope Gregory VII)', '约1015–1085', '托斯卡纳出身的修士，历任几位改革派教宗的顾问与执事长，是教会改革的核心人物。1073 年当选为教宗格列高利七世，禁止圣职买卖、教士婚姻与俗人授职，与亨利四世互相宣布废黜，1077 年在卡诺莎赦免了亨利。1084 年被诺曼人从罗马救出，次年死在萨莱诺。'],
  米海尔·普塞洛斯: ['Michael Psellos', '1018–约1078', '东罗马的学者、哲学家与宫廷大臣，复兴了柏拉图哲学的研究，是米海尔七世的老师。他的《编年史》记述了 976 至 1078 年的宫廷政治，许多事件是他亲眼所见。'],
  斯韦恩·埃斯特里德松: ['Sweyn II Estridsson', '约1019–1076', '克努特的外甥，以母名埃斯特里德为姓。1047 年成为丹麦国王，与挪威的哈拉尔作战多年，1064 年和解，1069 年派儿子们率舰队进攻英格兰。他是此后丹麦历代国王的祖先。'],
  马尔科姆三世: ['Malcolm III', '约1031–1093', '邓肯一世之子，在英格兰长大，1057 年杀死麦克白，次年即位，后来娶英格兰王族的玛格丽特为后。1072 年在阿伯内西向征服者威廉称臣，1093 年第五次南侵英格兰时在阿尼克战死。'],
  征服者威廉: ['William the Conqueror', '约1028–1087', '诺曼底公爵罗贝尔一世的私生子，七八岁继位，平定了诺曼底贵族的叛乱。1066 年渡海进攻英格兰，在黑斯廷斯打败哈罗德，圣诞节加冕为英格兰国王。此后镇压各地反抗，把土地分给诺曼贵族，1085 年下令编制末日审判书，1087 年死在鲁昂。'],
  罗贝尔·吉斯卡尔: ['Robert Guiscard', '约1015–1085', '欧特维尔家族的第六子，1047 年前后来到意大利，在卡拉布里亚当强盗起家，1059 年在梅尔菲受教宗册封为阿普利亚与卡拉布里亚公爵。他攻下巴里与巴勒莫，结束了东罗马在意大利的统治，1081 年渡海进攻东罗马，1084 年从亨利四世手中救出格列高利七世，次年死在凯法洛尼亚。'],
  阿韦尔萨的理查: ['Richard I of Capua', '?–1078', '雷努尔夫的侄子，阿韦尔萨伯爵，参加了奇维塔特之战，1058 年夺取卡普阿，1059 年受教宗册封为卡普阿亲王，1073 年向格列高利七世宣誓效忠。'],
  西西里的罗杰: ['Roger I of Sicily', '约1031–1101', '欧特维尔家族的幼子，罗贝尔·吉斯卡尔的弟弟，1061 年渡海攻下墨西拿，1072 年与兄长攻下巴勒莫，1091 年攻下诺托与马耳他，用三十年征服了西西里，成为西西里伯爵。'],
  优素福·本·塔士芬: ['Yusuf ibn Tashfin', '约1009–1106', '穆拉比特运动的领袖，修建了马拉喀什，征服了整个摩洛哥，1086 年渡海在萨拉卡打败卡斯蒂利亚国王阿方索六世，此后废黜泰法诸王，统一了安达卢斯。'],
  阿尔普·阿尔斯兰: ['Alp Arslan', '约1030–1072', '恰格里·贝格之子，1063 年继叔父图格里勒为塞尔柱苏丹，1064 年攻陷阿尼，1071 年在曼齐刻尔特俘虏了东罗马皇帝罗曼努斯四世，次年在河中被俘虏的守将刺死。'],
  // 卷二十九、三十共有
  罗贝尔·柯索斯: ['Robert Curthose', '约1051–1134', '征服者威廉的长子，“柯索斯”意为短袜，继承了诺曼底公国。1096 年把诺曼底抵押给弟弟，参加第一次十字军，回国后被弟弟亨利一世俘虏，囚禁至死。'],
  博希蒙德: ['Bohemond of Taranto', '约1054–1111', '罗贝尔·吉斯卡尔与第一位妻子的儿子，随父进攻东罗马，1083 年在拉里萨被阿莱克修斯击退。参加第一次十字军，靠内应攻下安条克，成为安条克亲王。'],
  达尼什曼德·加齐: ['Danishmend Gazi', '?–约1104', '突厥首领，曼齐刻尔特之后在锡瓦斯与卡帕多西亚一带建立达尼什曼德王朝，他的事迹后来被编成突厥语的英雄史诗。'],
  坦克雷德: ['Tancred', '约1075–1112', '博希蒙德的外甥，随舅父参加第一次十字军，先后取得西里西亚的塔尔苏斯与加利利，后来为博希蒙德摄政安条克。'],
  布洛涅的鲍德温: ['Baldwin of Boulogne', '约1060–1118', '布永的戈弗雷的弟弟，随兄长参加十字军，中途东去，1098 年建立埃德萨伯国。1100 年继兄长统治耶路撒冷，加冕为第一位耶路撒冷国王。'],
  沙特尔的富歇: ['Fulcher of Chartres', '1059–约1127', '法兰西的教士，可能亲耳听过乌尔班二世在克莱蒙的讲话，随布卢瓦的斯蒂芬参加十字军，后来做了鲍德温的随军神父，所写的《耶路撒冷史》记事到 1127 年。'],
  基利杰·阿尔斯兰一世: ['Kilij Arslan I', '1079–1107', '苏莱曼之子，1092 年从马利克沙的宫中逃回，继承罗姆苏丹国，1096 年歼灭隐士彼得的队伍，次年失去尼西亚，在多里留姆败于十字军，此后以科尼亚为都城。'],
  图卢兹的雷蒙: ['Raymond IV of Toulouse', '约1041–1105', '图卢兹伯爵兼普罗旺斯侯爵，曾在西班牙与穆斯林作战，是第一次十字军中最富有的诸侯，带着教宗使节阿德马尔同行。他拒绝了耶路撒冷的统治权，后来在黎巴嫩海边围攻的黎波里时去世。'],
  希梅娜: ['Jimena Díaz', '?–约1116', '阿斯图里亚斯贵族之女，阿方索六世的远亲，1074 年前后嫁给熙德。丈夫死后守卫巴伦西亚近三年，1102 年撤回卡斯蒂利亚。'],
  阿方索六世: ['Alfonso VI', '约1040–1109', '费尔南多一世之子，1065 年得莱昂，1072 年兄长桑乔二世被杀后继承卡斯蒂利亚，1085 年攻下托莱多，自称“两教皇帝”，1086 年在萨拉卡败于穆拉比特人。'],
  卡尔曼: ['Coloman', '约1070–1116', '拉斯洛一世的侄子，1095 年继位为匈牙利国王，1096 年击退了在匈牙利抢劫的十字军，1102 年加冕为克罗地亚国王。'],
  亨利四世: ['Henry IV', '1050–1106', '亨利三世之子，六岁即位，由母亲阿格妮丝与大主教们摄政。亲政后镇压萨克森人起义，与教宗格列高利七世争夺主教的授职权，1076 年被绝罚，次年在卡诺莎求得赦免。1084 年在罗马加冕为皇帝，晚年被儿子亨利五世逼迫退位。'],
  安瑟伦: ['Anselm of Canterbury', '1033–1109', '意大利奥斯塔人，兰弗朗克的学生，贝克修道院院长，1093 年继任坎特伯雷大主教，与两任国王为叙任权争执。著有《宣讲》《上帝为何成人》，被称为“经院哲学之父”。'],
  阿莱克修斯一世: ['Alexios I Komnenos', '约1057–1118', '科穆宁家族的将军，1081 年夺取帝位，先后击退诺曼人与佩切涅格人，向西方求援，在第一次十字军的帮助下收复了小亚细亚西部，开启了科穆宁王朝的中兴。'],
  安娜·科穆宁娜: ['Anna Komnene', '1083–1153', '阿莱克修斯一世的长女，受过完整的古典教育。父亲死后谋立丈夫为帝失败，退居修道院，写成《阿莱克修斯传》，记述了诺曼人的入侵与第一次十字军。'],
  加扎利: ['al-Ghazali', '1058–1111', '图斯出身的神学家与法学家，1091 年任巴格达尼扎米亚学院的主讲，1095 年弃职隐修，著有《宗教科学的复兴》与《哲学家的矛盾》。'],
  弗拉基米尔·莫诺马赫: ['Vladimir II Monomakh', '1053–1125', '弗谢沃洛德与东罗马公主之子，长年与库曼人作战，1097 年参与柳别奇会议，1113 年成为基辅大公，留下给子孙的《训诫》。'],
  托斯卡纳的马蒂尔达: ['Matilda of Tuscany', '1046–1115', '托斯卡纳边区伯爵卜尼法斯之女，统治从伦巴第到托斯卡纳的大片领地，是格列高利七世最坚定的支持者。1077 年亨利四世在她的卡诺莎城堡外求得赦免，她身后把领地遗赠给了教廷。'],
  建设者大卫: ['David IV the Builder', '1073–1125', '格鲁吉亚国王，1089 年十六岁即位，停止向塞尔柱人纳贡，1121 年在迪德戈里大败塞尔柱联军，次年收复第比利斯。'],
  阿夫达勒: ['al-Afdal Shahanshah', '1066–1121', '巴德尔·贾马利之子，1094 年继任大宰相，扶立穆斯塔阿里，1098 年收复耶路撒冷，次年在阿斯卡隆败于十字军。'],
  欧玛尔·海亚姆: ['Omar Khayyam', '1048–1131', '尼沙普尔出身的数学家与天文学家，参与修订哲拉理历，写过三次方程的几何解法，后世以他的波斯文四行诗闻名。'],
  // 卷三十、三十一共有
  萨拉丁: ['Saladin', '1137/38–1193', '库尔德人，生于提克里特，阿尤布之子，1169 年任埃及的维齐尔，1171 年终结法蒂玛王朝，1174 年后统一埃及与叙利亚，1187 年在哈丁大败十字军，收复耶路撒冷，1192 年与狮心王理查议和，次年三月死于大马士革。'],
  阿迪勒: ['al-Adil', '1145–1218', '萨拉丁的弟弟，第三次十字军时代表萨拉丁与理查谈判。萨拉丁死后诸子相争，他先后夺取大马士革与埃及，1200 年起为苏丹，重新统一了阿尤布王朝，把各地分给儿子们治理，1218 年在第五次十字军围攻杜米亚特时去世。'],
  狮心王理查: ['Richard I the Lionheart', '1157–1199', '亨利二世与埃莉诺之子，阿基坦公爵，1189 年继位，率领第三次十字军占领塞浦路斯与阿克，在阿尔苏夫击败萨拉丁，1192 年议和，回国途中被奥地利公爵扣押，交给皇帝亨利六世，1194 年赎回。此后与腓力二世连年交战，修建了盖亚尔城堡，1199 年在利穆赞围攻沙吕城堡时中箭身亡。'],
  亨利六世: ['Henry VI', '1165–1197', '腓特烈一世之子，娶西西里王位继承人康斯坦丝，1190 年继承德意志王位，1191 年加冕为皇帝，扣押了从圣地回国的狮心王理查，用赎金征服西西里，1194 年圣诞节在巴勒莫加冕，1197 年准备东征时在墨西拿病逝。'],
  阿基坦的埃莉诺: ['Eleanor of Aquitaine', '约1122–1204', '阿基坦公爵威廉十世之女，先嫁法兰西国王路易七世，随他参加第二次十字军，1152 年婚姻被宣布无效，随即嫁给亨利二世，生下理查与约翰，晚年为在德意志被扣的理查筹措赎金，七十多岁时还翻越比利牛斯山为孙女布朗什定亲，葬于丰特弗罗修道院。'],
  无地王约翰: ['John Lackland', '1166–1216', '亨利二世的幼子，父亲最宠爱的儿子，1189 年转投腓力二世与理查一方，1199 年继承哥哥理查的王位。他与腓力二世交战失去了诺曼底与安茹，与英诺森三世争执坎特伯雷大主教的人选，被绝罚后向教宗称臣。1214 年布汶之战后，英格兰贵族起兵，迫使他在兰尼米德签署大宪章，次年内战中病死。'],
  腓力二世: [['Philip II Augustus', '1165–1223', '路易七世之子，1180 年继位，挑拨亨利二世与诸子的关系，与狮心王理查一同参加第三次十字军，攻下阿克后回国。1204 年夺取诺曼底，1214 年在布汶击败奥托四世与佛兰德伯爵，王室领地扩大了几倍，在巴黎修建了城墙与卢浮宫城堡。', ['salading', 'jiaohuang']]],
  伊萨克二世: ['Isaac II Angelos', '约1156–1204', '安格洛斯家族的贵族，1185 年被民众拥立为帝，击退诺曼人，但未能平定保加利亚人的起义，1195 年被兄长阿莱克修斯三世刺瞎废黜，1203 年十字军攻城后复位，与儿子阿莱克修斯四世共治，次年在政变中死去。'],
  塔玛尔: ['Tamar of Georgia', '约1160–1213', '乔治三世之女，1184 年起独自统治格鲁吉亚，在位时格鲁吉亚最为强盛，被称为“国王”。1204 年她资助亲族在黑海南岸建立特拉布宗帝国，诗人鲁斯塔维利把史诗《虎皮武士》献给了她。'],
  伊本·鲁世德: ['Ibn Rushd (Averroes)', '1126–1198', '科尔多瓦的法官与医生，受穆瓦希德哈里发阿布·雅库布之托注释亚里士多德的全部著作，晚年一度被雅库布·曼苏尔放逐，1198 年死于马拉喀什。他的注释译成拉丁文后，欧洲学者称他为“注释家”。'],
  迈蒙尼德: ['Maimonides', '1138–1204', '生于科尔多瓦的犹太学者与医生，因穆瓦希德王朝的迫害随家人流亡，定居福斯塔特，做过萨拉丁的维齐尔的御医，著有《密西拿托拉》与《迷途指津》，1204 年去世，葬于提比利亚。'],
  // 卷三十一、三十二共有
  教宗英诺森四世: ['Innocent IV', '约1195–1254', '热那亚的菲耶斯基家族出身，博洛尼亚的教会法学家，1243 年当选教宗，次年逃往里昂，1245 年召开大公会议废黜腓特烈二世，派方济各会士出使蒙古。腓特烈死后他继续与霍亨斯陶芬家族为敌，1253 年为立陶宛的明道加斯派去主教加冕，1254 年在那不勒斯去世。'],
  英格兰的亨利三世: ['Henry III', '1207–1272', '约翰之子，九岁即位，由威廉·马歇尔摄政，1225 年再次颁布大宪章。他几次出兵想收复普瓦图都失败了，1259 年与路易九世订立巴黎条约。1258 年被贵族逼迫接受牛津条例，1264 年在刘易斯被西蒙·德·蒙福尔俘虏，伊夫舍姆之战后复位，晚年重建了威斯敏斯特修道院。'],
  路易九世: ['Louis IX', '1214–1270', '路易八世与卡斯蒂利亚的布朗什之子，十二岁即位，由母亲摄政。他以虔诚与公正著称，修建了圣礼拜堂，1248 年率领第七次十字军进攻埃及，在曼苏拉战败被俘，赎回后在阿克住了四年。1259 年与英格兰订立巴黎条约，1270 年再次出征，死在突尼斯城外，1297 年被封为圣徒。'],
  卡斯蒂利亚的布朗什: ['Blanche of Castile', '1188–1252', '卡斯蒂利亚国王阿方索八世与英格兰的埃莉诺之女，外祖母阿基坦的埃莉诺亲自到卡斯蒂利亚为她定亲，1200 年嫁给路易八世。两次为儿子路易九世摄政，1229 年与图卢兹伯爵订立巴黎条约，1252 年在儿子远在圣地时去世。'],
  费尔南多三世: ['Ferdinand III', '1199/1201–1252', '莱昂国王阿方索九世与卡斯蒂利亚公主贝伦格拉之子，1217 年得卡斯蒂利亚，1230 年继承莱昂，此后收复了科尔多瓦、哈恩、穆尔西亚与塞维利亚，1252 年死于塞维利亚，儿子阿方索十世继位，1671 年被封为圣徒。'],
  拜伯尔斯: ['Baybars', '约1223–1277', '钦察突厥人，少年时被卖为奴隶，成为萨利赫·阿尤布的河洲马穆鲁克，在曼苏拉之战中击败阿图瓦伯爵，1250 年参与刺杀图兰沙。1260 年在艾因贾鲁特击败蒙古军，随后刺杀苏丹忽都思自立，在位十七年间攻下了凯撒里亚、安条克与骑士堡等十字军的城市与城堡。'],
  拔都: ['Batu Khan', '约1205–1255', '成吉思汗长子术赤之子，1236 年统率长子西征，灭伏尔加保加尔人，征服罗斯诸公国，1241 年击败波兰与匈牙利的军队，东返后在伏尔加河下游建立萨莱，成为金帐汗国的创立者，1255 年去世。'],
  // 卷三十二、三十三共有
  腓力六世: ['Philip VI', '1293–1350', '腓力四世的侄子，瓦卢瓦伯爵查理之子，1328 年卡佩王朝的直系断绝后被立为国王，开创瓦卢瓦王朝。1337 年没收英格兰国王领有的阿基坦，引发百年战争，1340 年在斯鲁伊斯失去舰队，1346 年在克雷西大败，次年失去加来，1350 年去世。'],
  爱德华三世: ['Edward III', '1312–1377', '爱德华二世与法兰西的伊莎贝拉之子，1327 年十四岁继位，1330 年发动政变处死莫蒂默亲政。他以外祖父腓力四世的血统要求法兰西王位，1337 年起与法兰西开战，1340 年在斯鲁伊斯、1346 年在克雷西获胜，次年攻下加来，1360 年订立布雷蒂尼和约，创立嘉德骑士团，晚年失去了法兰西的大部分领地，在位五十年。'],
  巴伐利亚的路德维希: ['Louis IV the Bavarian', '1282–1347', '巴伐利亚公爵，1314 年被一部分诸侯选为国王，1322 年在米尔多夫击败哈布斯堡的对手，与阿维尼翁的教宗约翰二十二世长期争执，1328 年在罗马以罗马人民的名义加冕为皇帝，收留了马西利乌斯与奥卡姆的威廉。1346 年诸侯另选查理四世，次年他在打猎时去世。'],
  彼特拉克: ['Petrarch', '1304–1374', '佛罗伦萨流亡者之子，在阿维尼翁长大，搜集与校订古罗马作家的手稿，发现了西塞罗的书信，用意大利语写了献给劳拉的《歌集》，用拉丁文写了大量书信，1341 年在罗马卡皮托利山上被授予桂冠，被看作人文主义的先驱。'],
  安德罗尼库斯三世: ['Andronikos III Palaiologos', '1297–1341', '米海尔八世的曾孙，与祖父安德罗尼库斯二世内战多年，1328 年夺得帝位，1329 年在佩莱卡农败给奥尔汗，此后失去了尼西亚与尼科米底亚，1341 年去世，身后东罗马陷入内战。'],
  奥尔汗: ['Orhan', '约1281–1362', '奥斯曼一世之子，1326 年攻下布尔萨并以之为都城，1329 年在佩莱卡农击败东罗马皇帝，1331 年取得尼西亚，1337 年取得尼科米底亚，建立了常备的步兵。他娶了坎塔库泽努斯的女儿，儿子苏莱曼 1354 年占领加利波利，在欧洲站稳了脚跟。'],
  // 卷三十三、三十四共有
  冈特的约翰: ['John of Gaunt', '1340–1399', '爱德华三世的第三子，生于根特，娶兰开斯特家族的女继承人，成为兰开斯特公爵，英格兰最富有的贵族。他在父亲晚年与侄子理查二世年幼时主持朝政，庇护过威克利夫，1381 年他的萨伏伊宫被起义者烧毁。他的儿子后来夺取王位，成为亨利四世。'],
  理查二世: ['Richard II', '1367–1400', '黑太子之子，1377 年十岁继位，1381 年在史密斯菲尔德面对起义农民，后来亲政，专断引起贵族反对，1399 年被堂兄亨利废黜，次年死于狱中。'],
  约翰·威克利夫: ['John Wycliffe', '约1328–1384', '牛津的神学家，主张《圣经》是信仰的唯一权威，批评教会的财富与教宗的权力，后来否认圣餐变体说。他的追随者把《圣经》译成英文，被称为罗拉德派。'],
  法兰西的查理六世: ['Charles VI of France', '1368–1422', '查理五世之子，1380 年十一岁继位，由叔父们辅政，1388 年亲政。1392 年起患上间歇的精神病，弟弟奥尔良公爵与叔父、堂弟勃艮第公爵争夺朝政，法兰西陷入内战。1420 年他与英格兰订立特鲁瓦条约，立女婿亨利五世为继承人。'],
  勇敢者腓力: ['Philip the Bold', '1342–1404', '法兰西国王约翰二世的第四子，在普瓦捷与父亲一同被俘，1363 年受封勃艮第公国，1369 年娶佛兰德的女继承人。他是瓦卢瓦家族勃艮第公爵的始祖，在侄子查理六世年幼与发病时长期掌握朝政。'],
  教宗乌尔班六世: ['Urban VI', '约1318–1389', '那不勒斯人，原任巴里大主教，1378 年在罗马民众的压力下当选教宗，性情暴烈，与枢机们决裂，引发大分裂，后来还囚禁并处死了几位反对他的枢机。'],
  对立教宗克雷芒七世: ['Antipope Clement VII', '1342–1394', '日内瓦伯爵之子罗贝尔，任枢机时曾率雇佣兵在切塞纳屠杀居民，1378 年被反对乌尔班六世的枢机们选为教宗，回到阿维尼翁，得到法兰西等国的承认。'],
  匈牙利的路易一世: ['Louis I of Hungary', '1326–1382', '安茹家族出身的匈牙利国王，1342 年继位，两次远征那不勒斯为被杀的弟弟报仇，从威尼斯手中夺取达尔马提亚，1370 年起兼任波兰国王，号“大王”。'],
  德米特里·顿斯科伊: ['Dmitry Donskoy', '1350–1389', '莫斯科大公，九岁继位，1367 年起用石头修建克里姆林宫的城墙，1380 年在库利科沃击败马麦，号“顿斯科伊”。1382 年脱脱迷失火烧莫斯科，他被迫重新纳贡。后来被东正教会封为圣徒。'],
  帖木儿: ['Timur', '1336–1405', '河中巴鲁剌思部的贵族，年轻时腿部受伤，人称跛子帖木儿，1370 年击败盟友侯赛因成为河中之主，以撒马尔罕为都城，此后三十多年征战伊朗、金帐汗国、印度、叙利亚与小亚细亚，1402 年在安卡拉俘虏巴耶济德，1405 年在远征明朝的途中病死。'],
  伊本·赫勒敦: ['Ibn Khaldun', '1332–1406', '生于突尼斯的学者，先后在马格里布各王朝与格拉纳达做官，1377 年写完《历史绪论》，讨论王朝兴衰与社会的规律，晚年在开罗任法官，1401 年在大马士革城外见过帖木儿。'],
  穆拉德一世: ['Murad I', '约1326–1389', '奥尔汗之子，1362 年继位，占领阿德里安堡与色雷斯，1371 年在马里查河击败塞尔维亚领主，使巴尔干诸国成为附庸，组建了从战俘中挑选的新军。1389 年在科索沃战场上被一名塞尔维亚人刺杀。'],
  // 卷三十四、三十五共有
  英格兰的亨利六世: ['Henry VI of England', '1421–1471', '亨利五世与卡特琳之子，不满一岁即位为英格兰国王，按特鲁瓦条约又被宣布为法兰西国王，1431 年在巴黎加冕。他由叔父们辅政，成年后性情温和，几次精神失常，后来在玫瑰战争中被废。'],
  法兰西的查理七世: ['Charles VII of France', '1403–1461', '查理六世的第五子，兄长们先后去世后成为王太子。1418 年逃出巴黎，次年在蒙特罗的会面中勃艮第公爵被杀，1420 年被特鲁瓦条约剥夺继承权。父亲死后自立为国王，1429 年在贞德的帮助下到兰斯加冕，晚年把英格兰人逐出了除加来以外的法兰西全境。'],
  穆拉德二世: ['Murad II', '1404–1451', '穆罕默德一世之子，1421 年即位，次年围攻君士坦丁堡，1430 年攻下帖撒罗尼迦，收复了安纳托利亚的几个贝伊国。他后来两度把苏丹之位让给儿子穆罕默德二世，又两度复位。'],
  好人腓力: ['Philip the Good', '1396–1467', '无畏者约翰之子，1419 年继为勃艮第公爵，为报父仇与英格兰结盟，参与订立特鲁瓦条约。他先后取得荷兰、埃诺、布拉班特与卢森堡，1430 年设立金羊毛骑士团，宫廷以奢华著称，1435 年与查理七世和解。'],
  君士坦丁十一世: ['Constantine XI Palaiologos', '1405–1453', '曼努埃尔二世之子，在伯罗奔尼撒的摩里亚君主国治理一方，1430 年攻下帕特雷。1449 年即位为东罗马的末代皇帝，1453 年在君士坦丁堡的城墙上战死。'],
  航海家亨利: ['Henry the Navigator', '1394–1460', '若昂一世的第三子，1415 年参加攻占休达。此后以基督骑士团的财力派船沿非洲西海岸南下，船队发现了马德拉群岛与亚速尔群岛，1434 年越过了博哈多尔角。'],
  布鲁内莱斯基: ['Filippo Brunelleschi', '1377–1446', '佛罗伦萨的金匠出身，1401 年在洗礼堂铜门竞赛中输给吉贝尔蒂，此后去罗马研究古代建筑，研究出了线性透视法。1420 年起主持修建佛罗伦萨大教堂的穹顶，还设计了育婴堂与圣洛伦佐教堂。'],
  卢森堡的西吉斯蒙德: ['Sigismund of Luxembourg', '1368–1437', '查理四世之子，瓦茨拉夫四世的弟弟。1387 年成为匈牙利国王，1396 年率十字军在尼科波利斯大败，1410 年当选罗马人的国王，促成康斯坦茨会议，结束了教会的分裂，却未能保护胡斯。1419 年继承波希米亚，与胡斯派作战多年，1433 年在罗马加冕为皇帝。'],
  贞德: ['Joan of Arc', '约1412–1431', '洛林边境栋雷米村的农家女，自称听见圣徒的声音，1429 年到希农见查理七世，五月解了奥尔良之围，随后护送国王到兰斯加冕。1430 年在贡比涅被勃艮第人俘虏，卖给英格兰人，次年在鲁昂被教会法庭判为异端烧死。1456 年原判被撤销，1920 年被封为圣徒。'],
  贝德福德公爵约翰: ['John of Lancaster, Duke of Bedford', '1389–1435', '亨利四世的第三子，亨利五世的弟弟。兄长死后在法兰西为侄子亨利六世摄政，1424 年在韦尔讷伊获胜，努力维持与勃艮第的同盟，1435 年死在鲁昂。'],
  约翰八世·巴列奥略: ['John VIII Palaiologos', '1392–1448', '曼努埃尔二世的长子，1425 年即位为东罗马皇帝。他为了得到西方的援助，后来亲自去意大利参加费拉拉—佛罗伦萨会议，1439 年签署了东西方教会的合一协议。'],
  约盖拉: ['Jogaila (Władysław II Jagiełło)', '约1352–1434', '立陶宛大公阿尔吉尔达斯之子，1386 年受洗，与雅德维加成婚，成为波兰国王瓦迪斯瓦夫二世，开创雅盖隆王朝。他让立陶宛皈依基督教，1410 年与维陶塔斯一同在格伦瓦尔德击败条顿骑士团，在位四十八年。'],
  皮埃尔·科雄: ['Pierre Cauchon', '1371–1442', '巴黎大学的神学家，勃艮第派的支持者，1420 年任博韦主教。贞德在他的教区内被俘，他主持了鲁昂的异端审判。1456 年的平反审判宣布他主持的判决无效。'],
  沙哈鲁: ['Shah Rukh', '1377–1447', '帖木儿的第四子，父亲死后从赫拉特出发，打败争位的侄子，1409 年起统治帖木儿帝国的大部分地区，定都赫拉特，资助学术与艺术，与明朝互派使节。他的儿子兀鲁伯治理撒马尔罕，建立了天文台。'],
  扬·凡·艾克: ['Jan van Eyck', '约1390–1441', '尼德兰画家，1425 年起任好人腓力的宫廷画家与侍从，几次为公爵出使。他把油画技法发展到极其精细的程度，与兄长休伯特合作完成了根特祭坛画，作品还有《阿尔诺菲尼夫妇像》。'],
  大普罗科普: ['Prokop the Great', '约1380–1434', '已婚的教士，杰士卡死后的塔博尔派领袖。他带领胡斯派军队击败了第四、第五次十字军，出兵劫掠周边各国，1433 年代表胡斯派去巴塞尔会议谈判，次年在利帕尼被温和派与天主教贵族的联军击败战死。'],
  乔叟: ['Geoffrey Chaucer', '约1343–1400', '伦敦酒商之子，做过宫廷侍从、外交使节与伦敦港的关税官，多次出使法兰西与意大利。他用英语写作，代表作有《特洛伊罗斯与克丽西达》与未完成的《坎特伯雷故事》，葬在威斯敏斯特修道院，被称为英语诗歌之父。'],
  // 卷三十五、三十六共有
  卡克斯顿: ['William Caxton', '约1422–1491', '英格兰的商人，长期在布鲁日主持英格兰商人公会。他在科隆学习印刷，在布鲁日印出了第一本英文书，1476 年回国在威斯敏斯特开设英格兰第一家印刷所，印行了乔叟、马洛礼等人的作品。'],
  伊凡三世: ['Ivan III of Moscow', '1440–1505', '莫斯科大公瓦西里二世之子，1462 年继位，兼并了诺夫哥罗德、特维尔等罗斯公国，1472 年娶东罗马末代皇帝的侄女索菲亚，1480 年摆脱了金帐汗国的统治，自称全罗斯的君主。'],
  洛伦佐·德·美第奇: ['Lorenzo de\' Medici', '1449–1492', '科西莫的孙子，1469 年二十岁执掌佛罗伦萨，人称“伟大的洛伦佐”。他会写诗，资助学者与艺术家，1478 年在帕齐阴谋中幸免于难，晚年维持着意大利各国的均势。'],
  教宗西斯笃四世: ['Pope Sixtus IV', '1414–1484', '方济各会的神学家弗朗切斯科·德拉罗韦雷，1471 年当选教宗。他大力提拔亲族，修建了西斯廷礼拜堂，开放了梵蒂冈图书馆，后来卷入反对美第奇家族的帕齐阴谋。'],
  穆罕默德二世: ['Mehmed II', '1432–1481', '穆拉德二世之子，1451 年第二次即位，1453 年攻下君士坦丁堡，迁都于此，人称“征服者”。此后他吞并了塞尔维亚、摩里亚、特拉布宗、波斯尼亚与卡拉曼，与威尼斯作战十六年，1481 年在出征途中去世。'],
  卡斯蒂利亚的伊莎贝拉: ['Isabella I of Castile', '1451–1504', '卡斯蒂利亚国王胡安二世之女，1469 年自主嫁给阿拉贡王子费尔南多，1474 年即位为卡斯蒂利亚女王，经过王位继承战争站稳了脚跟，后来与丈夫一同征服格拉纳达，资助哥伦布航海。'],
  阿拉贡的费尔南多二世: ['Ferdinand II of Aragon', '1452–1516', '阿拉贡国王胡安二世之子，1469 年娶卡斯蒂利亚的伊莎贝拉，1479 年继为阿拉贡国王，与妻子共同统治两国，人称“天主教双王”。他夺取了那不勒斯与纳瓦拉，妻子死后为女儿胡安娜摄政卡斯蒂利亚，马基雅维利在《君主论》里称他为当时最著名的君主。'],
  路易十一: ['Louis XI of France', '1423–1483', '查理七世之子，青年时参加贵族的叛乱，与父亲长期不和，投奔勃艮第公爵。1461 年即位，用金钱、外交与间谍对付大诸侯，粉碎了公益同盟，1477 年大胆查理死后收回了勃艮第公国与皮卡第，人称“万能的蜘蛛”。'],
  马加什一世: ['Matthias Corvinus', '1443–1490', '匈雅提之子，1458 年被选为匈牙利国王。他建立了常备的黑军，从哈布斯堡、波希米亚手中夺得摩拉维亚、西里西亚与维也纳，宫廷里聚集了意大利的人文主义者，藏书馆闻名欧洲。'],
  哈布斯堡的马克西米利安: ['Maximilian I', '1459–1519', '腓特烈三世之子，1477 年娶勃艮第的玛丽，为保卫她的遗产与法兰西作战，1486 年当选罗马人的国王，1493 年继承父位，1508 年称皇帝。他推行帝国改革，在意大利战争中屡战屡败，却以儿子与孙辈的婚姻为哈布斯堡家族取得了西班牙，并为日后继承匈牙利与波希米亚铺了路。'],
  葡萄牙的阿方索五世: ['Afonso V of Portugal', '1432–1481', '杜阿尔特一世之子，六岁继位，在北非攻占了阿尔卡萨尔-塞吉尔、阿尔齐拉与丹吉尔，人称“非洲人”。1475 年为争夺卡斯蒂利亚的王位进兵，次年在托罗战败。'],
  勃艮第的玛丽: ['Mary of Burgundy', '1457–1482', '大胆查理的独女，父亲死后继承尼德兰等领地，签署《大特权》，1477 年嫁给哈布斯堡的马克西米利安。她五年后坠马去世，领地由儿子腓力继承。'],
  爱德华四世: ['Edward IV', '1442–1483', '约克公爵理查之子，父亲战死后于 1461 年在伦敦被拥立为国王，同年在陶顿大败兰开斯特派。1470 年被沃里克伯爵逐出英格兰，次年在巴尼特与图克斯伯里获胜复位，1475 年与路易十一订立皮基尼条约。'],
  哈布斯堡的腓特烈三世: ['Frederick III', '1415–1493', '哈布斯堡家族的施蒂里亚公爵，1440 年当选罗马人的国王，1452 年在罗马加冕为皇帝，是最后一位在罗马加冕的皇帝。他在位五十三年，曾被匈牙利国王马加什夺去维也纳，却凭联姻为家族取得了勃艮第的遗产。'],
  卡齐米日四世: ['Casimir IV Jagiellon', '1427–1492', '约盖拉的小儿子，1440 年任立陶宛大公，1447 年又继为波兰国王。他与条顿骑士团进行了十三年战争，取得王室普鲁士，儿子们后来做了波希米亚与匈牙利的国王。'],
  索菲亚·帕列奥罗格: ['Sophia Palaiologina', '约1449–1503', '摩里亚君主托马斯·巴列奥略之女，东罗马末代皇帝君士坦丁十一世的侄女，在罗马长大，1472 年嫁给莫斯科大公伊凡三世，把拜占庭的宫廷礼仪带到了莫斯科。'],
  列奥纳多·达·芬奇: ['Leonardo da Vinci', '1452–1519', '生于佛罗伦萨附近的芬奇镇，在韦罗基奥的画坊学艺，后来为米兰公爵、教宗与法兰西国王服务，是画家、工程师与博物学者，代表作有《最后的晚餐》与《蒙娜丽莎》。'],
  // 卷三十六、三十七共有
  亨利八世: ['Henry VIII', '1491–1547', '亨利七世的次子，1509 年继位，娶了哥哥的遗孀阿拉贡的凯瑟琳。早年参加对法兰西的战争，以学识与排场著称。1533 年为了离婚与罗马决裂，自任英格兰教会的最高首脑，解散修道院，先后娶过六位王后。'],
  伊拉斯谟: ['Desiderius Erasmus', '约 1466–1536', '鹿特丹人，奥古斯丁会修士出身的人文学者，游学巴黎、英格兰与意大利。著有《愚人颂》，1516 年出版希腊文新约，主张回到圣经与教父的原文，以学识与讽刺批评教会的弊病。他始终没有离开罗马教会，1524 年与路德就自由意志公开论战，1536 年死于巴塞尔。'],
  伊斯迈尔一世: ['Ismail I', '1487–1524', '萨法维教团首领之子，幼年丧父。1501 年率红头部众夺取大不里士，自称沙阿，以十二伊玛目派什叶派为国教，十年间统一伊朗，1514 年在查尔迪兰败于奥斯曼人。他以哈塔伊为笔名用阿塞拜疆突厥语写诗。'],
  卡斯蒂利亚的胡安娜: ['Joanna of Castile', '1479–1555', '伊莎贝拉与费尔南多之女，嫁给美男子腓力。1504 年继承卡斯蒂利亚王位，1516 年又名义上继承阿拉贡，但先后由丈夫、父亲与儿子查理掌权，自 1509 年起被幽禁在托尔德西利亚斯，人称“疯女胡安娜”。'],
  埃尔南·科尔特斯: ['Hernán Cortés', '1485–1547', '卡斯蒂利亚的贵族之子，在海地与古巴做过殖民者与书记官。1519 年违抗古巴总督的命令进军墨西哥，联合当地反对阿兹特克的部族，两年后攻占特诺奇蒂特兰。后来被封为侯爵，但没有得到新西班牙的治理权，晚年回到西班牙。'],
  塞利姆一世: ['Selim I', '1470–1520', '巴耶济德二世之子，1512 年迫使父亲退位。1514 年在查尔迪兰击败萨法维王朝，1516 至 1517 年灭马穆鲁克王朝，夺取了叙利亚、埃及与汉志。'],
  巴布尔: ['Babur', '1483–1530', '帖木儿的后裔，母系出自成吉思汗，费尔干纳的统治者。几次夺取撒马尔罕都被乌兹别克人逐出，1504 年南下夺取喀布尔，后来征服北印度，建立了莫卧儿帝国。'],
  弗朗索瓦一世: ['Francis I of France', '1494–1547', '路易十二的堂侄与女婿，1515 年继位，同年在马里尼亚诺大败瑞士人，夺回米兰。爱好艺术，把达·芬奇请到法兰西，1519 年竞选皇位败给查理五世。此后与查理五世四度交战，1525 年在帕维亚被俘，后来与奥斯曼人结盟。'],
  托马斯·莫尔: ['Thomas More', '1478–1535', '伦敦的律师与人文学者，伊拉斯谟的挚友。1516 年出版《乌托邦》，后来担任亨利八世的大法官，因拒绝承认国王为英格兰教会的首脑而被处死。'],
  教宗利奥十世: ['Pope Leo X', '1475–1521', '洛伦佐·德·美第奇之子，十三岁成为枢机主教，1513 年当选教宗。为修建圣彼得大教堂发售赎罪券，1520 年把路德逐出教会。'],
  查理五世: ['Charles V', '1500–1558', '美男子腓力与胡安娜之子，生长在尼德兰。1506 年继承尼德兰，1516 年继承卡斯蒂利亚与阿拉贡（称查理一世），1519 年继承奥地利并当选皇帝，统治着欧洲与美洲的大片领土。他一生与法兰西、奥斯曼人和德意志的新教诸侯作战，1555 至 1556 年把尼德兰、西班牙与帝国分别交给儿子腓力与弟弟斐迪南，退隐于西班牙的修道院。'],
  瓦西里三世: ['Vasily III', '1479–1533', '伊凡三世与索菲亚之子，1505 年继位。吞并了普斯科夫与梁赞，1514 年从立陶宛手中夺取斯摩棱斯克。'],
  米开朗琪罗: ['Michelangelo Buonarroti', '1475–1564', '佛罗伦萨的雕塑家、画家与建筑师，少年时在洛伦佐·德·美第奇家中学艺。作有《圣殇》、大卫像与西斯廷礼拜堂的天顶画，晚年主持圣彼得大教堂的穹顶设计。'],
  葡萄牙的曼努埃尔一世: ['Manuel I of Portugal', '1469–1521', '若昂二世的堂弟兼妻弟，1495 年继位。在位期间达伽马到达印度，卡布拉尔到达巴西，阿尔布克尔克在印度洋建立了葡萄牙的据点，香料贸易使里斯本成为欧洲最富庶的港口之一，人称“幸运王”。'],
  阿拉贡的凯瑟琳: ['Catherine of Aragon', '1485–1536', '伊莎贝拉与费尔南多的幼女，1501 年嫁给英格兰王子亚瑟，丈夫数月后死去，1509 年改嫁亨利八世。1513 年亨利出征法兰西时她留守摄政，调度了对苏格兰的战事。'],
  马丁·路德: ['Martin Luther', '1483–1546', '萨克森的奥古斯丁会修士，维滕堡大学的神学教授。1517 年提出九十五条论纲，质疑赎罪券，此后与罗马教会决裂，开启了宗教改革。1521 年在沃尔姆斯帝国议会上拒绝收回自己的著作，被宣布为法外之人，在瓦特堡把新约译成德文，后来娶了前修女卡塔琳娜·冯·博拉。'],
  马基雅维利: ['Niccolò Machiavelli', '1469–1527', '佛罗伦萨共和国的秘书，多次出使法兰西与切萨雷·博尔贾的军营。1512 年美第奇家族回来后被革职，在乡间写成《君主论》与《论李维》。'],
  麦哲伦: ['Ferdinand Magellan', '约 1480–1521', '葡萄牙贵族，曾在印度洋随阿尔梅达与阿尔布克尔克作战，到过马六甲。与葡萄牙国王不和，转投西班牙，1519 年率船队向西寻找香料群岛，穿过南美洲南端的海峡横渡太平洋，1521 年在菲律宾的麦克坦岛战死。'],
  齐格蒙特一世: ['Sigismund I the Old', '1467–1548', '卡齐米日四世的幼子，1506 年继兄长亚历山大为立陶宛大公与波兰国王。1515 年与马克西米利安会晤于维也纳，与哈布斯堡家族和解。'],
  // 卷三十七、三十八共有
  西班牙的腓力二世: ['Philip II of Spain', '1527–1598', '查理五世之子，1554 年娶英格兰女王玛丽一世，1555 至 1556 年从父亲手中接过尼德兰、西班牙、意大利与美洲的领地。'],
  奥地利的斐迪南一世: ['Ferdinand I', '1503–1564', '美男子腓力与胡安娜之子，查理五世的弟弟，生长在西班牙。1521 年起治理奥地利，1526 年当选波希米亚与匈牙利国王，与扎波利亚和奥斯曼人争夺匈牙利。代兄主持奥格斯堡和约，1556 年起接替哥哥治理帝国，1558 年称皇帝。'],
  奥兰治的威廉: ['William of Orange', '1533–1584', '拿骚家族的伯爵，十一岁继承奥兰治亲王的称号与尼德兰的大片领地，在查理五世的宫廷长大，1555 年查理退位时倚着他的肩膀。后来领导尼德兰反抗西班牙。'],
  若昂三世: ['John III of Portugal', '1502–1557', '曼努埃尔一世之子，1521 年继位。在巴西设立总督府，在国内设立宗教裁判所，把耶稣会请进葡萄牙，派沙勿略去东方传教。'],
  法兰西的亨利二世: ['Henry II of France', '1519–1559', '弗朗索瓦一世之子，幼年在马德里作人质，娶凯瑟琳·德·美第奇。1547 年继位，严厉镇压新教，1552 年与德意志新教诸侯结盟，占领梅斯、图勒与凡尔登。'],
  玛丽一世: ['Mary I of England', '1516–1558', '亨利八世与阿拉贡的凯瑟琳之女，1553 年即位，恢复天主教，次年嫁给西班牙的腓力，在位期间约有二百八十名新教徒被烧死。'],
  苏格兰的玛丽女王: ['Mary, Queen of Scots', '1542–1587', '詹姆斯五世之女，出生六天即为苏格兰女王，1548 年被送到法兰西，在法兰西宫廷长大，与王太子订婚。'],
  科西莫一世·德·美第奇: ['Cosimo I de\' Medici', '1519–1574', '美第奇家族旁支的后人，1537 年亚历山德罗被刺后被推为佛罗伦萨公爵，1555 年征服锡耶纳，后来被教宗封为托斯卡纳大公。'],
  图尔古特: ['Turgut Reis', '1485–1565', '安纳托利亚出身的海盗与海军将领，海雷丁的部下，1551 年参与攻下的黎波里，后任的黎波里总督，1565 年在马耳他之围中战死。'],
  希南: ['Mimar Sinan', '约 1490–1588', '安纳托利亚的基督徒少年，被征召入禁卫军，做过军中工兵。1539 年起任宫廷首席建筑师近五十年，设计了苏莱曼清真寺、埃迪尔内的塞利米耶清真寺等三百多座建筑。'],
  苏莱曼一世: ['Suleiman the Magnificent', '1494–1566', '塞利姆一世之子，1520 年继位。攻下贝尔格莱德与罗得岛，1526 年在莫哈赤消灭了匈牙利军队，1529 年围攻维也纳，1534 年夺取巴格达，1541 年占领布达。修订法典，奥斯曼人称他为“立法者”。'],
  齐格蒙特二世: ['Sigismund II Augustus', '1520–1572', '齐格蒙特一世与博娜·斯福尔扎之子，1548 年继位，雅盖隆家族的最后一位国王，1569 年促成波兰与立陶宛合为一国。'],
  伊凡四世: ['Ivan IV', '1530–1584', '瓦西里三世之子，三岁继位，1547 年加冕为沙皇。早年改革法典与军制，1552 年攻下喀山，1556 年吞并阿斯特拉罕，后来以残暴著称，人称“雷帝”。'],
  古斯塔夫·瓦萨: ['Gustav Vasa', '1496–1560', '瑞典贵族，父亲死于斯德哥尔摩惨案。率达拉纳的农民起兵赶走丹麦人，1523 年被选为瑞典国王，没收教会的财产，推行路德宗，建立了世袭的瓦萨王朝。'],
  塔赫马斯普一世: ['Tahmasp I', '1514–1576', '伊斯迈尔一世之子，十岁继位，在位五十二年。与奥斯曼人作战二十多年，1555 年订立阿马西亚和约，把都城迁到加兹温，曾收留逃亡的莫卧儿皇帝胡马雍。'],
  加尔文: ['John Calvin', '1509–1564', '法兰西皮卡第人，学习法律，皈依新教后流亡巴塞尔，1536 年出版《基督教要义》。此后主持日内瓦的教会改革，使日内瓦成为欧洲新教的中心之一。'],
  // 卷三十八、三十九共有
  塞万提斯: ['Miguel de Cervantes', '1547–1616', '阿尔卡拉的外科医生之子，青年时到意大利当兵，在勒班陀左手负伤，1575 年回国途中被阿尔及尔的海盗俘虏，五年后才被赎回。后来做过无敌舰队的军需征购员，1605 年出版《堂吉诃德》第一部。'],
  拿骚的莫里斯: ['Maurice of Nassau', '1567–1625', '奥兰治的威廉的次子，父亲遇刺后被推为荷兰与泽兰的执政，后来又任联省的陆军统帅。他整顿军队，推行密集的操练与轮射，1590 年代从西班牙人手中收复了许多城市，成为当时最著名的军事改革家。'],
  纳瓦拉的亨利: ['Henry IV of France', '1553–1610', '波旁家族的旺多姆公爵安托万与纳瓦拉女王让娜·达尔布雷之子，自幼信奉新教，1572 年继承纳瓦拉王位，同年娶瓦卢瓦的玛格丽特。1589 年继承法兰西王位为亨利四世，四年后改宗天主教，1598 年颁布南特敕令，1610 年遇刺。'],
  伊丽莎白一世: ['Elizabeth I', '1533–1603', '亨利八世与安妮·博林的女儿，母亲被处死时她不满三岁。玛丽一世在位时她因怀特叛乱被关进伦敦塔。1558 年继位，恢复英格兰教会，终身未婚，在位四十五年，击退了无敌舰队，她的时代是英格兰戏剧与航海的繁荣时期。'],
  沃尔特·雷利: ['Walter Raleigh', '约 1552–1618', '德文郡的乡绅，在爱尔兰作战后成为伊丽莎白一世的宠臣，1580 年代组织在北美洲罗阿诺克岛的殖民，以女王之名把那里命名为弗吉尼亚。他参加了 1596 年的加的斯之役，也是诗人与史家。'],
  莎士比亚: ['William Shakespeare', '1564–1616', '斯特拉特福的手套商之子，十八岁娶了安妮·哈瑟维。1590 年前后到伦敦做演员与剧作家，是宫务大臣剧团的股东，1599 年剧团修建了环球剧场。他一生写了三十多部历史剧、喜剧与悲剧，以及长诗与十四行诗。'],
  詹姆斯六世: ['James VI and I', '1566–1625', '苏格兰女王玛丽与达恩利勋爵之子，一岁继位，由几位摄政先后执政，受加尔文派的教育。1580 年代起亲政，与伊丽莎白一世结盟，1603 年继承英格兰王位，称詹姆斯一世，开始了两国的共主时代。'],
  鲁道夫二世: ['Rudolf II', '1552–1612', '马克西米利安二世的长子，少年时在西班牙宫廷受教育，1576 年继位，后来把宫廷迁到布拉格，收藏绘画、珍奇与机械，延揽第谷、开普勒与画家阿钦博托。他性情忧郁，终身未婚，晚年被弟弟马蒂亚斯夺去大部分领地。'],
  约翰内斯·开普勒: ['Johannes Kepler', '1571–1630', '符腾堡的路德宗信徒，在图宾根大学学神学时接受了哥白尼的学说。1594 年起在格拉茨教数学，1600 年到布拉格做第谷的助手，第谷死后接任皇家数学家，根据第谷的观测记录发现了行星运动的定律。'],
  伽利略: ['Galileo Galilei', '1564–1642', '佛罗伦萨音乐家文琴佐·伽利莱之子，生于比萨，在比萨大学学医，转而研究数学，1589 年起在比萨任教，1592 年转往帕多瓦。他研究落体与摆，后来用望远镜观测天体，支持哥白尼的学说。'],
  乔尔达诺·布鲁诺: ['Giordano Bruno', '1548–1600', '那不勒斯附近诺拉的多明我会修士，因异端嫌疑逃离修会，游历日内瓦、巴黎、伦敦与德意志，主张宇宙无限、有无数个世界。1592 年在威尼斯被捕，在罗马受审八年，1600 年在鲜花广场被烧死。'],
  穆罕默德三世: ['Mehmed III', '1566–1603', '穆拉德三世的长子，1595 年继位，即位时处死了十九个弟弟。他是最后一位在少年时出任行省总督的奥斯曼王子，1596 年亲征匈牙利，攻下埃格尔，赢得迈泽凯赖斯泰什之战。'],
  齐格蒙特三世: ['Sigismund III Vasa', '1566–1632', '瑞典国王约翰三世与波兰公主卡塔日娜之子，生在父亲被囚禁的城堡里，受耶稣会的教育。1587 年当选波兰国王，1592 年又继承瑞典王位，1599 年被瑞典议会废黜，后来把波兰的都城从克拉科夫迁到华沙。'],
  扬·扎莫伊斯基: ['Jan Zamoyski', '1542–1605', '波兰贵族，在巴黎与帕多瓦求学，以中小贵族的代言人身份在选举中崛起。巴托里在位时任大法官与王室统帅，1588 年在比奇纳击败并俘虏了奥地利大公马克西米利安，又仿照意大利的样式兴建了扎莫希奇城。'],
  勇敢的米哈伊: ['Michael the Brave', '1558–1601', '瓦拉几亚的贵族，1593 年在奥斯曼的支持下当上瓦拉几亚公爵，两年后起兵反抗奥斯曼。1599 至 1600 年他先后占领了特兰西瓦尼亚与摩尔达维亚，短暂地统一了三地，1601 年被哈布斯堡的将军暗杀。'],
  鲍里斯·戈杜诺夫: ['Boris Godunov', '约 1552–1605', '鞑靼裔的小贵族，在伊凡四世的特辖军中起家，妹妹伊琳娜嫁给了皇子费奥多尔。费奥多尔在位时他实际掌权，设立莫斯科牧首区，与瑞典订约收复了芬兰湾沿岸的城市。1598 年当选沙皇，晚年遇到大饥荒与冒称德米特里的人起兵。'],
  克里斯蒂安四世: ['Christian IV', '1577–1648', '弗雷德里克二世之子，十一岁继位，1596 年亲政，在位六十年，是丹麦在位最久的国王。他兴建了哥本哈根的许多建筑与几座新城，后来卷入三十年战争。'],
  第谷·布拉赫: ['Tycho Brahe', '1546–1601', '丹麦的贵族，少年时看到日食，从此迷上天文学，在打斗中失去了鼻子，戴着金属的假鼻。1572 年观测到新星，在汶岛上修建了天堡与星堡两座天文台，二十年间以前所未有的精度测量行星与恒星的位置。1597 年离开丹麦，后来做了鲁道夫二世的皇家数学家。'],
  阿拔斯一世: ['Abbas I', '1571–1629', '萨法维沙阿穆罕默德·胡达班达之子，在呼罗珊长大，1588 年被部落首领拥立为沙阿。他先与奥斯曼人议和，整编军队，削弱部落首领的势力，1598 年收复赫拉特，迁都伊斯法罕，后来又从奥斯曼人手中夺回了失地。'],
  阿克巴: ['Akbar', '1542–1605', '莫卧儿皇帝胡马雍之子，1556 年十三岁继位，在帕尼帕特击败了争夺德里的军队。他征服了印度北部与中部的大部分地区，与拉其普特诸王联姻，废除了对非穆斯林的人头税，主持各宗教的辩论，建立了统一的行政与税收制度。'],
  艾哈迈德·曼苏尔: ['Ahmad al-Mansur', '1549–1603', '阿卜杜勒·马利克的弟弟，三王之战后继位，用葡萄牙贵族的赎金与蔗糖贸易致富，在马拉喀什修建巴迪宫。他与伊丽莎白一世通使，1591 年派兵越过撒哈拉击败桑海帝国，取得了尼日尔河流域的金子。'],
  // 卷三十九、四十共有
  斐迪南三世: ['Ferdinand III', '1608–1657', '斐迪南二世之子，华伦斯坦死后统率帝国军队，1634 年在讷德林根获胜。1637 年继位，面对法兰西与瑞典的进攻，最终签署了威斯特伐利亚和约。他也是作曲家。'],
  克里斯蒂娜女王: ['Christina of Sweden', '1626–1689', '古斯塔夫·阿道夫唯一的女儿，六岁继位，1644 年亲政，热心学术，邀请格劳秀斯与笛卡尔来到斯德哥尔摩。1654 年她让位给表兄，改宗天主教，移居罗马。'],
  马萨林: ['Cardinal Mazarin', '1602–1661', '西西里人，在罗马为教廷做外交官，1630 年代转为法兰西效力，深得黎塞留赏识，1641 年成为红衣主教。黎塞留死后接任首席大臣，在路易十四年幼时与王太后安妮共掌朝政，主持了威斯特伐利亚的谈判。'],
  奥地利的安妮: ['Anne of Austria', '1601–1666', '西班牙国王腓力三世的女儿，十四岁嫁给路易十三，婚姻冷淡，曾被怀疑与西班牙通信。1643 年为四岁的儿子路易十四摄政，倚重马萨林，在投石党之乱中坚持不让步。'],
  路易十四: ['Louis XIV', '1638–1715', '路易十三与奥地利的安妮之子，四岁继位，童年经历了投石党之乱，1661 年马萨林死后亲政，在位七十二年，人称“太阳王”。'],
  大孔代: ['Louis II de Bourbon, Prince of Condé', '1621–1686', '波旁家族的亲王，二十一岁以昂吉安公爵的身份统兵，1643 年在罗克鲁瓦大败西班牙军，此后又在弗赖堡、讷德林根、朗斯获胜，是当时最著名的将领之一，后来卷入投石党之乱。'],
  勒内·笛卡尔: ['René Descartes', '1596–1650', '都兰的贵族之子，在耶稣会学校读书，青年时在拿骚的莫里斯与巴伐利亚的军中服役。1628 年起定居荷兰二十年，发表《谈谈方法》《第一哲学沉思集》《哲学原理》，创立解析几何，1650 年应克里斯蒂娜女王之邀到斯德哥尔摩，几个月后病死。'],
  西班牙的腓力四世: ['Philip IV of Spain', '1605–1665', '腓力三世之子，十六岁继位，在位四十四年。他爱好戏剧与绘画，提拔委拉斯开兹为宫廷画师，前二十二年由奥利瓦雷斯执政，此后西班牙失去了葡萄牙，承认了荷兰的独立。'],
  若昂四世: ['John IV of Portugal', '1604–1656', '布拉干萨公爵，葡萄牙最富有的贵族，曼努埃尔一世的后裔。1640 年被起事的贵族拥立为王，开创布拉干萨王朝，与英格兰、法兰西结盟抵抗西班牙。他也是音乐家与藏书家。'],
  英格兰的查理一世: ['Charles I', '1600–1649', '詹姆斯一世的次子，1625 年继位，娶法兰西公主亨丽埃塔·玛丽亚。他相信君权神授，宠信白金汉公爵，十一年不开议会，在苏格兰推行祈祷书引发战争，1642 年与议会开战，战败被俘，1649 年被议会审判处死。'],
  奥利弗·克伦威尔: ['Oliver Cromwell', '1599–1658', '亨廷登的乡绅，虔诚的清教徒，1640 年当选剑桥的议员。内战中他组建纪律严明的骑兵，在马斯顿荒原与内斯比获胜，成为新模范军的实际领袖，后来主导了审判国王，1653 年起任护国主。'],
  穆罕默德四世: ['Mehmed IV', '1642–1693', '易卜拉欣之子，六岁继位，先后由祖母柯塞姆与母亲图尔汗摄政，1656 年起由柯普律吕家族的大维齐尔执政，在位将近四十年，喜好打猎，人称“猎人”。'],
  博格丹·赫梅利尼茨基: ['Bohdan Khmelnytsky', '约 1595–1657', '乌克兰的哥萨克百人长，受过耶稣会学校的教育，曾在采措拉被奥斯曼人俘虏。1647 年他的庄园被波兰贵族夺走，次年逃到扎波罗热起事，联合克里米亚汗国大败波兰军，建立了哥萨克国家，1654 年在佩列亚斯拉夫向沙皇效忠。'],
  阿列克谢一世: ['Alexis of Russia', '1629–1676', '米哈伊尔·罗曼诺夫之子，十六岁继位，性情温和虔诚，人称“最安静的沙皇”。在位时颁布 1649 年法典，接受乌克兰哥萨克的归附，与波兰争夺乌克兰，支持牧首尼康的宗教改革，引起了旧礼仪派的分裂。'],
  阿拔斯二世: ['Abbas II', '1632–1666', '萨菲之子，九岁继位，成年后亲理政务，1648 年从莫卧儿人手中收复坎大哈，在伊斯法罕修建了四十柱宫，在位时伊朗大体安定。'],
  沙贾汉: ['Shah Jahan', '1592–1666', '贾汉吉尔之子，本名胡拉姆，1628 年继位，在位时莫卧儿帝国最为富庶。他为亡妻修建了泰姬陵，在德里修建了红堡与新城沙贾汉纳巴德，晚年被儿子奥朗则布囚禁。'],
  // 卷三十九、四十共有
  迭戈·委拉斯开兹: ['Diego Velázquez', '1599–1660', '塞维利亚人，1623 年为腓力四世画像后被召入宫廷，此后一直是国王的画师，两度去意大利。他画王室成员、侏儒、神话与《布雷达的投降》，晚年画了《宫娥》。'],
  吉安·洛伦佐·贝尼尼: ['Gian Lorenzo Bernini', '1598–1680', '那不勒斯出生的雕塑家与建筑师，少年成名，为博尔盖塞红衣主教雕了《阿波罗与达芙妮》，为圣彼得大教堂修建了青铜华盖与后来的柱廊广场，是罗马巴洛克艺术的代表。'],
  伦勃朗: ['Rembrandt van Rijn', '1606–1669', '莱顿的磨坊主之子，1631 年迁居阿姆斯特丹，以肖像画与群像成名，1642 年画了民兵连的群像，后称《夜巡》。他一生画了近百幅自画像，晚年破产，光影的运用独步一时。'],
  // 卷四十、四十一共有
  沃邦: ['Sébastien Le Prestre de Vauban', '1633–1707', '勃艮第的小贵族，早年在孔代麾下作战，后来为国王效力。他主持了几十次围城，设计、改建了法兰西边境上的一百多座要塞，以壕沟逐层推进的方法攻城，晚年任法兰西元帅，写过主张按收入普遍征税的著作。'],
  詹姆斯二世: ['James II', '1633–1701', '查理一世之子，在苏格兰称詹姆斯七世。复辟后任海军大臣，在英荷战争中亲自指挥舰队，纽约以他约克公爵的爵号命名。他公开改信天主教，1685 年继位，1688 年在光荣革命中出逃法兰西，1690 年在爱尔兰的博因河战败，晚年住在圣日耳曼昂莱。'],
  玛丽二世: ['Mary II', '1662–1694', '约克公爵詹姆斯的长女，按查理二世的安排以新教教养长大，1677 年嫁给表兄奥兰治的威廉三世，住在荷兰。光荣革命后与丈夫共同继承英格兰与苏格兰的王位，丈夫出征时代为主政，1694 年死于天花。'],
  艾萨克·牛顿: ['Isaac Newton', '1643–1727', '林肯郡自耕农之子，遗腹子。1665 年剑桥因瘟疫停课时回乡，研究了微积分、光的色散与引力。1669 年任剑桥的卢卡斯数学教授，造出反射望远镜，1687 年出版《自然哲学的数学原理》。后来任皇家铸币厂的总监，1703 年起任王家学会会长，1704 年出版《光学》。'],
  埃德蒙·哈雷: ['Edmond Halley', '1656–1742', '伦敦肥皂商之子，年轻时在圣赫勒拿岛测绘南天星图。他劝说牛顿写出《原理》并自费出版，1705 年计算出一颗彗星的周期约为七十六年，预言它将在 1758 年回归，后来任格林尼治的王家天文学家。'],
  奥兰治的威廉三世: ['William III of Orange', '1650–1702', '奥兰治亲王威廉二世的遗腹子，母亲是查理一世的女儿玛丽。1672 年法军入侵时被推举为执政与统帅，此后一生组织反对路易十四的同盟。1677 年娶表妹玛丽，1688 年出兵英格兰，次年与妻子共同继承王位，在博因河击败詹姆斯二世，1702 年坠马受伤后去世，没有子女。'],
  利奥波德一世: ['Leopold I', '1640–1705', '斐迪南三世的次子，原本准备做神职人员，兄长早逝后 1658 年当选皇帝，在位近半个世纪。他与路易十四多次作战，1683 年维也纳被围时出逃，此后收复匈牙利。他喜爱音乐，自己作曲。'],
  卡洛斯二世: ['Charles II of Spain', '1661–1700', '腓力四世的儿子，三岁继位，由母亲摄政。他是哈布斯堡家族几代近亲婚姻的后代，自幼体弱多病，两次婚姻都没有子女，西班牙的继承问题成为欧洲列国争夺的焦点。临终时立遗嘱把西班牙留给路易十四的孙子安茹公爵。'],
  葡萄牙的佩德罗二世: ['Peter II of Portugal', '1648–1706', '若昂四世之子，1667 年废黜哥哥阿方索六世，以摄政的身份统治，娶了哥哥的王后，1668 年与西班牙订约，结束了二十八年的独立战争。1683 年阿方索死后正式称王。'],
  卡尔十一世: ['Charles XI', '1655–1697', '卡尔十世之子，四岁继位，由摄政会议统治。斯科讷战争中亲自领兵在隆德击败丹麦人。此后召开议会收回贵族占有的王室土地，建立了瑞典的专制君主制。'],
  克里斯蒂安五世: ['Christian V', '1646–1699', '弗雷德里克三世之子，1670 年继位，重用格里芬菲尔德，1683 年颁布统一的《丹麦法典》。他在斯科讷战争中试图收复斯科讷，海战获胜，但没能得到土地。'],
  扬三世·索别斯基: ['John III Sobieski', '1629–1696', '波兰大贵族，在对哥萨克、瑞典与鞑靼人的战争中成名，1668 年任王室大统领。1673 年在霍京大败奥斯曼军，次年当选国王，1683 年率军解救维也纳。他在维拉努夫修建了宫殿。'],
  彼得大帝: ['Peter I the Great', '1672–1725', '阿列克谢一世与第二位妻子纳塔利娅·纳雷什金娜之子，1682 年十岁时与异母兄伊凡五世同为沙皇，由姐姐索菲亚摄政，1689 年推翻索菲亚，1696 年起独自统治。他化名随大使团游历西欧，学习造船，回国后剪胡子、改历法、建海军与常备军，在大北方战争中击败瑞典，修建新都圣彼得堡，设立元老院与各部委员会，1721 年称全俄罗斯皇帝。'],
  索菲亚·阿列克谢耶芙娜: ['Sophia Alekseyevna', '1657–1704', '阿列克谢一世的女儿，受过良好的教育。1682 年射击军暴动后为两个弟弟伊凡五世与彼得摄政，由宠臣瓦西里·戈利岑主持政务，1686 年与波兰订立永久和约，1689 年与清朝订立尼布楚条约。同年被彼得推翻，关进新圣女修道院，死在那里。'],
  苏莱曼二世: ['Suleiman II', '1642–1691', '易卜拉欣一世之子，穆罕默德四世的弟弟，在宫中的幽禁里度过了四十多年，1687 年兄长被废后继位。'],
  戈特弗里德·莱布尼茨: ['Gottfried Wilhelm Leibniz', '1646–1716', '莱比锡大学道德哲学教授之子，二十岁获法学博士，做过美因茨选帝侯的外交官，1672 至 1676 年在巴黎，结识惠更斯，独立发明了微积分。此后长年做汉诺威公爵家族的图书馆员与史官，还设计了能做乘除的计算机。'],
  奥朗则布: ['Aurangzeb', '1618–1707', '沙贾汉的第三子，1658 年在继承战争中击败兄弟们，囚禁父亲，自立为帝。他严守逊尼派教法，1679 年恢复对非穆斯林征收人头税，此后长年在德干作战，莫卧儿帝国的疆域在他手中达到最大。'],
};
const commonOf = (n, id) => { const v = Object.prototype.hasOwnProperty.call(PEOPLE_COMMON, n) ? PEOPLE_COMMON[n] : null; if (!v) return null; return (Array.isArray(v[0]) ? v : [v]).find(c => !c[3] || c[3].includes(id)) || null; };
